// Count nodes in the list
func countNodes(head *ListNode) int {
    count := 0
    curr := head
    for curr != nil {
        count++
        curr = curr.Next
    }
    return count
}

// Remove all nodes with a given value
func removeElements(head *ListNode, val int) *ListNode {
    // Create dummy node pointing to head
    dummy := &ListNode{Next: head}
    curr := dummy

    for curr.Next != nil {
        if curr.Next.Val == val {
            // Skip the node by pointing around it
            curr.Next = curr.Next.Next
        } else {
            curr = curr.Next
        }
    }

    return dummy.Next  // Return actual head (might have changed)
}

// Example: removeElements(1->2->6->3->6, 6) returns 1->2->3

// Find the middle node
// When fast reaches the end, slow is at the middle
func findMiddle(head *ListNode) *ListNode {
    slow := head
    fast := head

    for fast != nil && fast.Next != nil {
        slow = slow.Next       // Move 1 step
        fast = fast.Next.Next  // Move 2 steps
    }

    return slow  // This is the middle node
}

// Example: 1->2->3->4->5
// slow: 1 -> 2 -> 3
// fast: 1 -> 3 -> 5 -> nil
// Middle is 3

func hasCycle(head *ListNode) bool {
    slow := head
    fast := head

    for fast != nil && fast.Next != nil {
        slow = slow.Next
        fast = fast.Next.Next

        if slow == fast {
            return true  // They met, there's a cycle!
        }
    }

    return false  // Fast reached the end, no cycle
}

func reverseList(head *ListNode) *ListNode {
    var prev *ListNode = nil  // Previous node (starts as nil)
    curr := head              // Current node

    for curr != nil {
        next := curr.Next  // Save next node
        curr.Next = prev   // Reverse the link
        prev = curr        // Move prev forward
        curr = next        // Move curr forward
    }

    return prev  // prev is now the new head
}

// Before: 1 -> 2 -> 3 -> nil
// After:  3 -> 2 -> 1 -> nil

type TreeNode struct {
    Val   int        // The value stored in this node
    Left  *TreeNode  // Pointer to left child (nil if none)
    Right *TreeNode  // Pointer to right child (nil if none)
}

// Create this tree:
//       1
//      / \
//     2   3
//    / \
//   4   5

root := &TreeNode{Val: 1}
root.Left = &TreeNode{Val: 2}
root.Right = &TreeNode{Val: 3}
root.Left.Left = &TreeNode{Val: 4}
root.Left.Right = &TreeNode{Val: 5}

//       1
//      / \
//     2   3
// Inorder: 2, 1, 3

func inorderTraversal(root *TreeNode) []int {
    result := []int{}

    var inorder func(node *TreeNode)
    inorder = func(node *TreeNode) {
        if node == nil {
            return
        }
        inorder(node.Left)              // Visit left subtree
        result = append(result, node.Val) // Visit current node
        inorder(node.Right)             // Visit right subtree
    }

    inorder(root)
    return result
}

//       1
//      / \
//     2   3
// Preorder: 1, 2, 3

func preorderTraversal(root *TreeNode) []int {
    result := []int{}

    var preorder func(node *TreeNode)
    preorder = func(node *TreeNode) {
        if node == nil {
            return
        }
        result = append(result, node.Val) // Visit current node first
        preorder(node.Left)               // Then left subtree
        preorder(node.Right)              // Then right subtree
    }

    preorder(root)
    return result
}

//       1        Level 0
//      / \
//     2   3      Level 1
//    / \
//   4   5        Level 2
// Level order: [[1], [2, 3], [4, 5]]

func levelOrder(root *TreeNode) [][]int {
    if root == nil {
        return nil
    }

    result := [][]int{}
    queue := []*TreeNode{root}

    for len(queue) > 0 {
        levelSize := len(queue)  // Number of nodes at current level
        level := []int{}

        for i := 0; i < levelSize; i++ {
            // Dequeue
            node := queue[0]
            queue = queue[1:]

            level = append(level, node.Val)

            // Enqueue children for next level
            if node.Left != nil {
                queue = append(queue, node.Left)
            }
            if node.Right != nil {
                queue = append(queue, node.Right)
            }
        }

        result = append(result, level)
    }

    return result
}

func maxDepth(root *TreeNode) int {
    if root == nil {
        return 0
    }

    leftDepth := maxDepth(root.Left)
    rightDepth := maxDepth(root.Right)

    // Return 1 (this node) + the deeper subtree
    if leftDepth > rightDepth {
        return leftDepth + 1
    }
    return rightDepth + 1
}

//       1          depth 1
//      / \
//     2   3        depth 2
//    /
//   4              depth 3
// maxDepth = 3

func isSameTree(p *TreeNode, q *TreeNode) bool {
    // Both nil - equal
    if p == nil && q == nil {
        return true
    }
    // One nil, one not - not equal
    if p == nil || q == nil {
        return false
    }
    // Different values - not equal
    if p.Val != q.Val {
        return false
    }
    // Recursively check both subtrees
    return isSameTree(p.Left, q.Left) && isSameTree(p.Right, q.Right)
}

