// Your type must implement these 5 methods:
// 1. Len() int           - how many elements
// 2. Less(i, j int) bool - is element i less than j? (defines min vs max)
// 3. Swap(i, j int)      - swap elements at positions i and j
// 4. Push(x any)         - add an element
// 5. Pop() any           - remove and return the last element

import "container/heap"

// IntHeap is a min heap of integers
type IntHeap []int

// Len returns the number of elements
func (h IntHeap) Len() int { return len(h) }

// Less defines the order: h[i] < h[j] means min heap
func (h IntHeap) Less(i, j int) bool { return h[i] < h[j] }

// Swap swaps two elements
func (h IntHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }

// Push adds an element (called by heap.Push)
func (h *IntHeap) Push(x any) {
    *h = append(*h, x.(int))
}

// Pop removes and returns the last element (called by heap.Pop)
func (h *IntHeap) Pop() any {
    old := *h
    n := len(old)
    x := old[n-1]
    *h = old[:n-1]
    return x
}

