// MaxHeap - only change is in Less()
type MaxHeap []int

func (h MaxHeap) Len() int { return len(h) }
func (h MaxHeap) Less(i, j int) bool { return h[i] > h[j] }  // > for max heap!
func (h MaxHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }

func (h *MaxHeap) Push(x any) { *h = append(*h, x.(int)) }
func (h *MaxHeap) Pop() any {
    old := *h
    x := old[len(old)-1]
    *h = old[:len(old)-1]
    return x
}

// Usage: largest element is always at (*h)[0]

import "container/heap"

func findKLargest(nums []int, k int) []int {
    h := &IntHeap{}  // Min heap
    heap.Init(h)

    for _, num := range nums {
        heap.Push(h, num)

        // If heap is too big, remove the smallest
        if h.Len() > k {
            heap.Pop(h)
        }
    }

    // The heap now contains the K largest elements
    result := make([]int, k)
    for i := k - 1; i >= 0; i-- {
        result[i] = heap.Pop(h).(int)
    }
    return result
}

