type Counter struct {
    Value int
}

// WRONG: Receives a copy, changes are lost
func incrementWrong(c Counter) {
    c.Value++
    fmt.Println("Inside function:", c.Value)
}

// RIGHT: Receives a pointer, modifies original
func incrementRight(c *Counter) {
    c.Value++
    fmt.Println("Inside function:", c.Value)
}

func main() {
    counter := Counter{Value: 0}

    fmt.Println("Before incrementWrong:", counter.Value) // 0
    incrementWrong(counter)                               // prints 1
    fmt.Println("After incrementWrong:", counter.Value)  // still 0!

    fmt.Println()

    fmt.Println("Before incrementRight:", counter.Value) // 0
    incrementRight(&counter)                              // prints 1
    fmt.Println("After incrementRight:", counter.Value)  // now 1!
}

