    Next  *List
}

// Safe: checks for nil before accessing fields
func (l *List) Sum() int {
    if l == nil {
        return 0 // Base case: empty list
    }
    return l.Value + l.Next.Sum() // Recursive call
}

// Also safe: returns sensible value for nil
func (l *List) Length() int {
    if l == nil {
        return 0
    }
    return 1 + l.Next.Length()
}

