    var empty *List = nil
    fmt.Println("Empty sum:", empty.Sum())     // 0 (no panic!)
    fmt.Println("Empty length:", empty.Length()) // 0

    // Build a small list: 1 -> 2 -> 3 -> nil
    list := &List{Value: 1, Next: &List{Value: 2, Next: &List{Value: 3}}}
    fmt.Println("List sum:", list.Sum())       // 6
    fmt.Println("List length:", list.Length()) // 3
}

