import "fmt"

func describe(v any) string {
    // x gets the concrete value with the correct type in each case
    switch x := v.(type) {
    case nil:
        return "nil value"
    case int:
        // Here x is an int, so we can do arithmetic
        return fmt.Sprintf("integer: %d (doubled: %d)", x, x*2)
    case string:
        // Here x is a string, so we can use len()
        return fmt.Sprintf("string of length %d: %q", len(x), x)
    case bool:
        if x {
            return "boolean: true"
        }
        return "boolean: false"
    case []int:
        // Here x is []int, so we can range over it
        sum := 0
        for _, n := range x {
            sum += n
        }
        return fmt.Sprintf("int slice, sum = %d", sum)
    default:
        return fmt.Sprintf("unknown type: %T", x)
    }
}

func main() {
    fmt.Println(describe(42))           // integer: 42 (doubled: 84)
    fmt.Println(describe("hello"))     // string of length 5: "hello"
    fmt.Println(describe(true))         // boolean: true
    fmt.Println(describe([]int{1,2,3})) // int slice, sum = 6
    fmt.Println(describe(3.14))         // unknown type: float64
}

