import "fmt"

// Small, focused interfaces (like the standard library)
type Reader interface {
    Read(p []byte) (n int, err error)
}

type Writer interface {
    Write(p []byte) (n int, err error)
}

type Closer interface {
    Close() error
}

// Composed interfaces - embed smaller ones
type ReadWriter interface {
    Reader // Must have Read()
    Writer // Must have Write()
}

type ReadWriteCloser interface {
    Reader
    Writer
    Closer // Must have all three methods
}

// File implements all three methods
type File struct {
    name   string
    closed bool
}

func (f *File) Read(p []byte) (int, error) {
    fmt.Printf("Reading from %s\n", f.name)
    return 0, nil
}

func (f *File) Write(p []byte) (int, error) {
    fmt.Printf("Writing to %s\n", f.name)
    return len(p), nil
}

func (f *File) Close() error {
    fmt.Printf("Closing %s\n", f.name)
    f.closed = true
    return nil
}

func main() {
    file := &File{name: "test.txt"}

    // File satisfies all composed interfaces
    var rw ReadWriter = file
    var rwc ReadWriteCloser = file

    rw.Write([]byte("hello"))
    rwc.Close()
}

