func MustParseConfig(data []byte) *Config {
    cfg, err := ParseConfig(data)
    if err != nil {
        panic("MustParseConfig: " + err.Error())
    }
    return cfg
}

func main() {
    // Safe: handle the error
    cfg, err := ParseConfig([]byte("host=localhost"))
    if err != nil {
        fmt.Println("Error:", err)
        return
    }
    fmt.Printf("Parsed config: %s:%d\n", cfg.Host, cfg.Port)

    // Must* version: use only when you're SURE it won't fail
    // Typically used in init() or for hardcoded values
}

