func readFile(path string) ([]byte, error) {
    f, err := os.Open(path)
    if err != nil {
        return nil, err
    }
    defer f.Close() // Scheduled to run when function exits

    // Even if we return early here, f.Close() runs
    info, err := f.Stat()
    if err != nil {
        return nil, err // f.Close() still runs!
    }

    // Read the file contents
    data := make([]byte, info.Size())
    _, err = f.Read(data)
    if err != nil {
        return nil, err // f.Close() still runs!
    }

    return data, nil // f.Close() runs after return
}

func main() {
    // Create a test file
    os.WriteFile("test.txt", []byte("Hello, defer!"), 0644)
    defer os.Remove("test.txt") // Clean up test file

    data, err := readFile("test.txt")
    if err != nil {
        fmt.Println("Error:", err)
        return
    }
    fmt.Printf("Read: %s\n", data)
}

