import (
    "fmt"
    "os"
)

// Named return 'err' can be modified by defer
func writeFile(path string, data []byte) (err error) {
    f, err := os.Create(path)
    if err != nil {
        return err
    }

    // Defer that handles close error properly
    defer func() {
        closeErr := f.Close()
        // Only override err if no prior error occurred
        if err == nil && closeErr != nil {
            err = fmt.Errorf("close file: %w", closeErr)
        }
    }()

    _, err = f.Write(data)
    if err != nil {
        return fmt.Errorf("write data: %w", err)
    }

    return nil // Defer runs, may modify err
}

func main() {
    err := writeFile("output.txt", []byte("Hello, World!"))
    if err != nil {
        fmt.Println("Error:", err)
    } else {
        fmt.Println("File written successfully")
    }

    // Cleanup
    os.Remove("output.txt")
}

