import (
    "fmt"
    "sync"
    "time"
)

// Pattern 1: Mutex unlock - prevents deadlocks
type SafeCounter struct {
    mu    sync.Mutex
    count int
}

func (c *SafeCounter) Increment() {
    c.mu.Lock()
    defer c.mu.Unlock() // Always unlocks, even if panic
    c.count++
}

func (c *SafeCounter) Value() int {
    c.mu.Lock()
    defer c.mu.Unlock()
    return c.count
}

// Pattern 2: Timing operations
func slowOperation(name string) {
    start := time.Now()
    defer func() {
        fmt.Printf("%s took %v\n", name, time.Since(start))
    }()

    // Simulate work
    time.Sleep(50 * time.Millisecond)
}

// Pattern 3: Tracing function entry/exit
func trace(name string) func() {
    fmt.Printf("Entering %s\n", name)
    start := time.Now()
    return func() {
        fmt.Printf("Exiting %s (took %v)\n", name, time.Since(start))
    }
}

func processData() {
    defer trace("processData")()
    time.Sleep(25 * time.Millisecond)
}

func main() {
    counter := &SafeCounter{}
    counter.Increment()
    counter.Increment()
    fmt.Println("Count:", counter.Value())

    slowOperation("database query")
    processData()
}

