    "os"
)

// WRONG: All files stay open until function ends!
func processFilesBad(paths []string) error {
    for _, path := range paths {
        f, err := os.Open(path)
        if err != nil {
            return err
        }
        defer f.Close() // Piles up! 1000 files = 1000 open handles

        // Process file...
        fmt.Println("Processing:", path)
    }
    return nil // All 1000 files close HERE
}

// RIGHT: Extract to helper function
func processOneFile(path string) error {
    f, err := os.Open(path)
    if err != nil {
        return err
    }
    defer f.Close() // Closes when THIS function exits

    // Process file...
    fmt.Println("Processing:", path)
    return nil
}

func processFilesGood(paths []string) error {
    for _, path := range paths {
        if err := processOneFile(path); err != nil {
            return err
        }
        // File is already closed before next iteration
    }
    return nil
}

// ALTERNATIVE: Use anonymous function in loop
func processFilesAlternative(paths []string) error {
    for _, path := range paths {
        err := func() error {
            f, err := os.Open(path)
            if err != nil {
                return err
            }
            defer f.Close() // Closes when anonymous func exits

            fmt.Println("Processing:", path)
            return nil
        }()
        if err != nil {
            return err
        }
    }
    return nil
}

func main() {
    // Create test files
    for i := 1; i <= 3; i++ {
        os.WriteFile(fmt.Sprintf("file%d.txt", i), []byte("test"), 0644)
    }
    defer func() {
        for i := 1; i <= 3; i++ {
            os.Remove(fmt.Sprintf("file%d.txt", i))
        }
    }()

    paths := []string{"file1.txt", "file2.txt", "file3.txt"}
    processFilesGood(paths)
}

