import "fmt"

func mightPanic(shouldPanic bool) {
    if shouldPanic {
        panic("something went terribly wrong")
    }
    fmt.Println("mightPanic completed normally")
}

// Convert panic to error using named return
func safeCall(shouldPanic bool) (err error) {
    defer func() {
        if r := recover(); r != nil {
            // Convert panic value to error
            err = fmt.Errorf("recovered from panic: %v", r)
        }
    }()

    mightPanic(shouldPanic)
    return nil
}

func main() {
    // Case 1: No panic
    err := safeCall(false)
    if err != nil {
        fmt.Println("Error:", err)
    } else {
        fmt.Println("Call 1 succeeded")
    }

    // Case 2: Panic recovered
    err = safeCall(true)
    if err != nil {
        fmt.Println("Error:", err)
    } else {
        fmt.Println("Call 2 succeeded")
    }

    // Program continues running!
    fmt.Println("Program still running after recovered panic")
}

