import (
    "fmt"
    "log"
    "net/http"
    "runtime/debug"
)

// Recovery middleware that catches panics
func recoveryMiddleware(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        defer func() {
            if err := recover(); err != nil {
                // Log the panic with stack trace
                log.Printf("Panic: %v\n%s", err, debug.Stack())

                // Return 500 to client
                http.Error(w, "Internal Server Error", http.StatusInternalServerError)
            }
        }()

        next.ServeHTTP(w, r)
    })
}

// Handler that works normally
func helloHandler(w http.ResponseWriter, r *http.Request) {
    fmt.Fprintf(w, "Hello, World!")
}

// Handler that panics (simulating a bug)
func buggyHandler(w http.ResponseWriter, r *http.Request) {
    var data []string
    // This will panic: index out of range
    fmt.Fprintf(w, "Data: %s", data[0])
}

func main() {
    mux := http.NewServeMux()
    mux.HandleFunc("/hello", helloHandler)
    mux.HandleFunc("/buggy", buggyHandler)

    // Wrap all handlers with recovery middleware
    handler := recoveryMiddleware(mux)

    fmt.Println("Server starting on :8080")
    fmt.Println("Try: curl http://localhost:8080/hello")
    fmt.Println("Try: curl http://localhost:8080/buggy")
    log.Fatal(http.ListenAndServe(":8080", handler))
}

