import (
    "fmt"
    "time"
)

// Check if a time is today
func isToday(t time.Time) bool {
    now := time.Now()
    y1, m1, d1 := now.Date()
    y2, m2, d2 := t.Date()
    return y1 == y2 && m1 == m2 && d1 == d2
}

// Get start of day (midnight)
func startOfDay(t time.Time) time.Time {
    y, m, d := t.Date()
    return time.Date(y, m, d, 0, 0, 0, 0, t.Location())
}

// Get end of day (23:59:59)
func endOfDay(t time.Time) time.Time {
    y, m, d := t.Date()
    return time.Date(y, m, d, 23, 59, 59, 999999999, t.Location())
}

// Check if time is within business hours
func isBusinessHours(t time.Time) bool {
    hour := t.Hour()
    weekday := t.Weekday()

    // Monday through Friday, 9 AM to 5 PM
    isWeekday := weekday >= time.Monday && weekday <= time.Friday
    isWorkHour := hour >= 9 && hour < 17

    return isWeekday && isWorkHour
}

// Format relative time ("2 hours ago")
func timeAgo(t time.Time) string {
    d := time.Since(t)

    switch {
    case d < time.Minute:
        return "just now"
    case d < time.Hour:
        return fmt.Sprintf("%.0f minutes ago", d.Minutes())
    case d < 24*time.Hour:
        return fmt.Sprintf("%.0f hours ago", d.Hours())
    default:
        return fmt.Sprintf("%.0f days ago", d.Hours()/24)
    }
}

func main() {
    now := time.Now()
    yesterday := now.Add(-24 * time.Hour)

    fmt.Println("Is now today?", isToday(now))
    fmt.Println("Is yesterday today?", isToday(yesterday))

    fmt.Println("Start of today:", startOfDay(now).Format("15:04:05"))
    fmt.Println("End of today:", endOfDay(now).Format("15:04:05"))

    fmt.Println("Business hours now?", isBusinessHours(now))

    twoHoursAgo := now.Add(-2 * time.Hour)
    fmt.Println("Time ago:", timeAgo(twoHoursAgo))
}

