    // All matches (-1 means no limit)
    all := emailRe.FindAllString(text, -1)
    fmt.Println("All emails:", all) // [alice@example.com bob@company.org support@help.io]

    // Limited matches
    firstTwo := emailRe.FindAllString(text, 2)
    fmt.Println("First two:", firstTwo) // [alice@example.com bob@company.org]

    // Find with index (position in string)
    digitRe := regexp.MustCompile(`\d+`)
    numText := "abc123def456"

    loc := digitRe.FindStringIndex(numText)
    fmt.Printf("First number at position %d-%d: %s\n", 
        loc[0], loc[1], numText[loc[0]:loc[1]]) // 3-6: 123

    // All matches with indices
    allLocs := digitRe.FindAllStringIndex(numText, -1)
    fmt.Println("All number positions:", allLocs) // [[3 6] [9 12]]
}

