)

func main() {
    // Parse log entries: [date] LEVEL: message
    logRe := regexp.MustCompile(`\[(\d{4}-\d{2}-\d{2})\] (\w+): (.+)`)
    log := "[2024-01-15] ERROR: Connection to database failed"

    matches := logRe.FindStringSubmatch(log)
    if matches != nil {
        fmt.Println("Full match:", matches[0])
        fmt.Println("Date:", matches[1])      // 2024-01-15
        fmt.Println("Level:", matches[2])     // ERROR
        fmt.Println("Message:", matches[3])   // Connection to database failed
    }

    // Parse URL
    urlRe := regexp.MustCompile(`(https?)://([^/]+)(/.*)?`)
    url := "https://example.com/path/to/page"

    parts := urlRe.FindStringSubmatch(url)
    if parts != nil {
        fmt.Println("\nURL parts:")
        fmt.Println("Protocol:", parts[1])  // https
        fmt.Println("Host:", parts[2])      // example.com
        fmt.Println("Path:", parts[3])      // /path/to/page
    }

    // Named groups with (?P<name>...)
    namedRe := regexp.MustCompile(`(?P<year>\d{4})-(?P<month>\d{2})-(?P<day>\d{2})`)
    date := "2024-07-15"

    match := namedRe.FindStringSubmatch(date)
    names := namedRe.SubexpNames()

    fmt.Println("\nNamed groups:")
    for i, name := range names {
        if name != "" {
            fmt.Printf("%s: %s\n", name, match[i])
        }
    }

    // Find all matches with groups
    allLogRe := regexp.MustCompile(`(\w+)@(\w+\.\w+)`)
    emails := "Contact alice@example.com and bob@company.org"

    allMatches := allLogRe.FindAllStringSubmatch(emails, -1)
    fmt.Println("\nAll email parts:")
    for _, m := range allMatches {
        fmt.Printf("User: %s, Domain: %s\n", m[1], m[2])
    }
}

