)

func main() {
    // Simple replacement
    phoneRe := regexp.MustCompile(`\d{3}-\d{4}`)
    text := "Call 555-1234 or 555-5678 for help"
    redacted := phoneRe.ReplaceAllString(text, "XXX-XXXX")
    fmt.Println(redacted) // Call XXX-XXXX or XXX-XXXX for help

    // Using captured groups: reformat dates MM/DD/YYYY to YYYY-MM-DD
    dateRe := regexp.MustCompile(`(\d{2})/(\d{2})/(\d{4})`)
    dates := "Events on 01/15/2024 and 07/04/2024"
    isoFormat := dateRe.ReplaceAllString(dates, "$3-$1-$2")
    fmt.Println(isoFormat) // Events on 2024-01-15 and 2024-07-04

    // Named group replacement
    namedDateRe := regexp.MustCompile(`(?P<month>\d{2})/(?P<day>\d{2})/(?P<year>\d{4})`)
    result := namedDateRe.ReplaceAllString("Date: 12/25/2024", "${year}-${month}-${day}")
    fmt.Println(result) // Date: 2024-12-25

    // Dynamic replacement with function
    wordRe := regexp.MustCompile(`\b\w+\b`)
    sentence := "hello world"
    upper := wordRe.ReplaceAllStringFunc(sentence, strings.ToUpper)
    fmt.Println(upper) // HELLO WORLD

    // More complex function: censor certain words
    badWords := regexp.MustCompile(`(?i)\b(bad|ugly|wrong)\b`)
    input := "This is bad and ugly but not wrong"
    censored := badWords.ReplaceAllStringFunc(input, func(s string) string {
        return strings.Repeat("*", len(s))
    })
    fmt.Println(censored) // This is *** and **** but not *****
}

