import (
    "fmt"
    "regexp"
    "strconv"
)

// Apache Common Log Format parser
var logRe = regexp.MustCompile(
    `^(\S+) \S+ \S+ \[([^\]]+)\] "(\w+) ([^"]+) HTTP/[^"]+" (\d+) (\d+|-)`,
)

type LogEntry struct {
    IP         string
    Timestamp  string
    Method     string
    Path       string
    StatusCode int
    Size       int
}

func parseLogLine(line string) (*LogEntry, error) {
    matches := logRe.FindStringSubmatch(line)
    if matches == nil {
        return nil, fmt.Errorf("line does not match log format")
    }

    statusCode, _ := strconv.Atoi(matches[5])
    size := 0
    if matches[6] != "-" {
        size, _ = strconv.Atoi(matches[6])
    }

    return &LogEntry{
        IP:         matches[1],
        Timestamp:  matches[2],
        Method:     matches[3],
        Path:       matches[4],
        StatusCode: statusCode,
        Size:       size,
    }, nil
}

func main() {
    logs := []string{
        `192.168.1.1 - - [15/Jan/2024:10:30:45 +0000] "GET /index.html HTTP/1.1" 200 1234`,
        `10.0.0.5 - - [15/Jan/2024:10:31:00 +0000] "POST /api/users HTTP/1.1" 201 567`,
        `172.16.0.100 - - [15/Jan/2024:10:32:15 +0000] "GET /missing HTTP/1.1" 404 -`,
    }

    for _, log := range logs {
        entry, err := parseLogLine(log)
        if err != nil {
            fmt.Println("Parse error:", err)
            continue
        }
        fmt.Printf("%s %s %s -> %d (%d bytes)\n",
            entry.IP, entry.Method, entry.Path, entry.StatusCode, entry.Size)
    }
}

