import "fmt"

// Method 1: Add 1 to iota
type Month int
const (
    January Month = iota + 1 // 1
    February                 // 2
    March                    // 3
    // ... etc
)

// Method 2: Use blank identifier to skip zero
type Status int
const (
    _             Status = iota // 0 (discarded)
    StatusPending               // 1
    StatusActive                // 2
    StatusDone                  // 3
)

// Method 3: Make zero meaningful
type Priority int
const (
    PriorityUnknown Priority = iota // 0 = explicitly "unknown"
    PriorityLow                      // 1
    PriorityMedium                   // 2
    PriorityHigh                     // 3
)

func main() {
    // The danger of starting at 0
    var month Month // zero value is 0
    if month == 0 {
        fmt.Println("Month was never set (zero value)")
    }
    // If January were 0, we couldn't distinguish!

    // With Month starting at 1:
    var m Month
    if m == 0 {
        fmt.Println("Month not set")
    }
    m = March
    fmt.Println("Month:", m) // 3

    // Status with skipped zero
    var s Status
    fmt.Println("Unset status:", s) // 0 (not a valid status)
    s = StatusActive
    fmt.Println("Active status:", s) // 2

    // Priority with meaningful zero
    var p Priority
    fmt.Println("Default priority:", p) // 0 = PriorityUnknown
}

