import "fmt"

type Permission uint

const (
    PermRead    Permission = 1 << iota // 1 (binary: 001)
    PermWrite                          // 2 (binary: 010)
    PermExecute                        // 4 (binary: 100)
)

func (p Permission) String() string {
    result := ""
    if p&PermRead != 0 {
        result += "r"
    } else {
        result += "-"
    }
    if p&PermWrite != 0 {
        result += "w"
    } else {
        result += "-"
    }
    if p&PermExecute != 0 {
        result += "x"
    } else {
        result += "-"
    }
    return result
}

func main() {
    // Combine permissions with OR
    readWrite := PermRead | PermWrite
    fmt.Println("ReadWrite:", readWrite) // rw-

    all := PermRead | PermWrite | PermExecute
    fmt.Println("All:", all) // rwx

    // Check for specific permission with AND
    if readWrite&PermRead != 0 {
        fmt.Println("Has read permission")
    }
    if readWrite&PermExecute == 0 {
        fmt.Println("No execute permission")
    }

    // Remove a permission with AND NOT
    noWrite := all &^ PermWrite
    fmt.Println("After removing write:", noWrite) // r-x

    // Toggle a permission with XOR
    toggled := readWrite ^ PermExecute
    fmt.Println("After toggling execute:", toggled) // rwx
}

