import "fmt"

const (
    _  = iota             // 0 (skip)
    KB = 1 << (10 * iota) // 1 << 10 = 1024
    MB                    // 1 << 20 = 1,048,576
    GB                    // 1 << 30 = 1,073,741,824
    TB                    // 1 << 40 = 1,099,511,627,776
)

func formatBytes(bytes int64) string {
    switch {
    case bytes >= TB:
        return fmt.Sprintf("%.2f TB", float64(bytes)/float64(TB))
    case bytes >= GB:
        return fmt.Sprintf("%.2f GB", float64(bytes)/float64(GB))
    case bytes >= MB:
        return fmt.Sprintf("%.2f MB", float64(bytes)/float64(MB))
    case bytes >= KB:
        return fmt.Sprintf("%.2f KB", float64(bytes)/float64(KB))
    default:
        return fmt.Sprintf("%d B", bytes)
    }
}

func main() {
    fmt.Println("KB =", KB)
    fmt.Println("MB =", MB)
    fmt.Println("GB =", GB)

    // Use in calculations
    maxFileSize := 50 * MB
    fmt.Println("Max file size:", formatBytes(int64(maxFileSize)))

    cacheSize := 2 * GB
    fmt.Println("Cache size:", formatBytes(int64(cacheSize)))

    diskUsage := int64(1_500_000_000)
    fmt.Println("Disk usage:", formatBytes(diskUsage))
}

