package main

import (
    "fmt"
    "sync"
    "time"
)

type Job struct {
    ID   int
    Data string
}

type Result struct {
    JobID  int
    Output string
}

func worker(id int, jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
    defer wg.Done()
    for job := range jobs {
        // Simulate work
        time.Sleep(50 * time.Millisecond)
        results <- Result{
            JobID:  job.ID,
            Output: fmt.Sprintf("Worker %d processed: %s", id, job.Data),
        }
    }
    fmt.Printf("Worker %d: shutting down\n", id)
}

func main() {
    numWorkers := 3
    numJobs := 10

    jobs := make(chan Job, numJobs)
    results := make(chan Result, numJobs)

    // Start workers
    var wg sync.WaitGroup
    for w := 1; w <= numWorkers; w++ {
        wg.Add(1)
        go worker(w, jobs, results, &wg)
    }

    // Send jobs
    for j := 1; j <= numJobs; j++ {
        jobs <- Job{ID: j, Data: fmt.Sprintf("task-%d", j)}
    }
    close(jobs) // Signal no more jobs

    // Close results after all workers done
    go func() {
        wg.Wait()
        close(results)
    }()

    // Collect results
    for r := range results {
        fmt.Printf("Result: Job %d -> %s\n", r.JobID, r.Output)
    }

    fmt.Println("All jobs completed")
}

package main

import (
    "fmt"
    "sync"
    "time"
)

// Generator produces values
func generate(nums ...int) <-chan int {
    out := make(chan int)
    go func() {
        for _, n := range nums {
            out <- n
        }
        close(out)
    }()
    return out
}

// Worker processes values (fan-out: multiple call this)
func square(id int, in <-chan int) <-chan int {
    out := make(chan int)
    go func() {
        for n := range in {
            time.Sleep(50 * time.Millisecond) // Simulate work
            fmt.Printf("Worker %d: squaring %d\n", id, n)
            out <- n * n
        }
        close(out)
    }()
    return out
}

// Fan-in: merge multiple channels into one
func merge(channels ...<-chan int) <-chan int {
    out := make(chan int)
    var wg sync.WaitGroup

    for _, ch := range channels {
        wg.Add(1)
        go func(c <-chan int) {
            defer wg.Done()
            for v := range c {
                out <- v
            }
        }(ch)
    }

    go func() {
        wg.Wait()
        close(out)
    }()

    return out
}

func main() {
    // Generate numbers
    nums := generate(1, 2, 3, 4, 5, 6, 7, 8)

    // Fan-out: 3 workers process the same input channel
    w1 := square(1, nums)
    w2 := square(2, nums)
    w3 := square(3, nums)

    // Fan-in: merge all worker outputs
    results := merge(w1, w2, w3)

    // Collect results
    fmt.Println("\nResults (order varies):")
    for r := range results {
        fmt.Println(r)
    }
}

