import (
    "context"
    "fmt"
    "strings"
)

// Stage 1: Generate lines
func generate(ctx context.Context, lines ...string) <-chan string {
    out := make(chan string)
    go func() {
        defer close(out)
        for _, line := range lines {
            select {
            case out <- line:
            case <-ctx.Done():
                return
            }
        }
    }()
    return out
}

// Stage 2: Normalize (lowercase, trim)
func normalize(ctx context.Context, in <-chan string) <-chan string {
    out := make(chan string)
    go func() {
        defer close(out)
        for s := range in {
            normalized := strings.ToLower(strings.TrimSpace(s))
            select {
            case out <- normalized:
            case <-ctx.Done():
                return
            }
        }
    }()
    return out
}

// Stage 3: Filter (keep non-empty)
func filter(ctx context.Context, in <-chan string) <-chan string {
    out := make(chan string)
    go func() {
        defer close(out)
        for s := range in {
            if s != "" {
                select {
                case out <- s:
                case <-ctx.Done():
                    return
                }
            }
        }
    }()
    return out
}

// Stage 4: Transform (add prefix)
func transform(ctx context.Context, in <-chan string) <-chan string {
    out := make(chan string)
    go func() {
        defer close(out)
        for s := range in {
            result := fmt.Sprintf("[PROCESSED] %s", s)
            select {
            case out <- result:
            case <-ctx.Done():
                return
            }
        }
    }()
    return out
}

func main() {
    ctx := context.Background()

    // Input data
    lines := []string{
        "  Hello World  ",
        "GO PROGRAMMING",
        "   ",
        "Concurrency Patterns",
        "",
        "Pipeline Example",
    }

    // Build pipeline: generate -> normalize -> filter -> transform
    pipeline := transform(ctx,
        filter(ctx,
            normalize(ctx,
                generate(ctx, lines...))))

    // Consume output
    fmt.Println("Pipeline output:")
    for result := range pipeline {
        fmt.Println(result)
    }
}

