)

func main() {
    requests := []string{"req-1", "req-2", "req-3", "req-4", "req-5"}

    // Simple rate limiter: 2 requests per second
    fmt.Println("=== Simple Rate Limiter (2/sec) ===")
    limiter := time.Tick(500 * time.Millisecond) // 2 per second

    start := time.Now()
    for _, req := range requests {
        <-limiter // Wait for permission
        fmt.Printf("%s processed at %v\n", req, time.Since(start).Round(time.Millisecond))
    }

    // Bursty rate limiter: allow initial burst
    fmt.Println("\n=== Bursty Rate Limiter (burst of 3, then 2/sec) ===")
    burstyLimiter := make(chan time.Time, 3) // Buffer for burst

    // Pre-fill for initial burst
    for i := 0; i < 3; i++ {
        burstyLimiter <- time.Now()
    }

    // Refill at steady rate
    go func() {
        for t := range time.Tick(500 * time.Millisecond) {
            burstyLimiter <- t
        }
    }()

    requests2 := []string{"burst-1", "burst-2", "burst-3", "burst-4", "burst-5"}
    start = time.Now()
    for _, req := range requests2 {
        <-burstyLimiter
        fmt.Printf("%s processed at %v\n", req, time.Since(start).Round(time.Millisecond))
    }
}

