import (
    "fmt"
    "sync"
    "time"
)

func main() {
    tasks := []string{"A", "B", "C", "D", "E", "F", "G", "H"}
    maxConcurrent := 3

    // Semaphore: buffered channel limits concurrency
    sem := make(chan struct{}, maxConcurrent)
    var wg sync.WaitGroup

    start := time.Now()

    for _, task := range tasks {
        wg.Add(1)

        // Acquire semaphore (blocks if maxConcurrent already running)
        sem <- struct{}{}

        go func(t string) {
            defer wg.Done()
            defer func() { <-sem }() // Release semaphore

            fmt.Printf("[%v] Starting task %s\n", 
                time.Since(start).Round(time.Millisecond), t)

            time.Sleep(100 * time.Millisecond) // Simulate work

            fmt.Printf("[%v] Completed task %s\n", 
                time.Since(start).Round(time.Millisecond), t)
        }(task)
    }

    wg.Wait()
    fmt.Printf("\nAll tasks completed in %v\n", time.Since(start).Round(time.Millisecond))
    fmt.Printf("With %d concurrent, 8 tasks of 100ms each = ~%dms\n", 
        maxConcurrent, (len(tasks)/maxConcurrent+1)*100)
}

