import (
    "context"
    "errors"
    "fmt"
    "time"
)

// Simulated errgroup (actual: golang.org/x/sync/errgroup)
type Group struct {
    wg     chan error
    ctx    context.Context
    cancel context.CancelFunc
    err    error
}

func WithContext(ctx context.Context) (*Group, context.Context) {
    ctx, cancel := context.WithCancel(ctx)
    return &Group{wg: make(chan error, 100), ctx: ctx, cancel: cancel}, ctx
}

func (g *Group) Go(f func() error) {
    go func() {
        if err := f(); err != nil {
            g.cancel()
            g.wg <- err
        } else {
            g.wg <- nil
        }
    }()
}

func (g *Group) Wait() error {
    return g.err
}

// Demo without external dependency
func fetchURL(ctx context.Context, url string, shouldFail bool) error {
    fmt.Printf("Fetching %s...\n", url)

    select {
    case <-time.After(100 * time.Millisecond):
        if shouldFail {
            return fmt.Errorf("failed to fetch %s", url)
        }
        fmt.Printf("Fetched %s successfully\n", url)
        return nil
    case <-ctx.Done():
        fmt.Printf("Cancelled fetching %s\n", url)
        return ctx.Err()
    }
}

func main() {
    // Example 1: All succeed
    fmt.Println("=== All URLs succeed ===")
    ctx1, cancel1 := context.WithCancel(context.Background())
    var firstErr1 error
    done1 := make(chan struct{})

    go func() {
        urls := []string{"url1.com", "url2.com", "url3.com"}
        errs := make(chan error, len(urls))

        for _, url := range urls {
            url := url
            go func() {
                errs <- fetchURL(ctx1, url, false)
            }()
        }

        for range urls {
            if err := <-errs; err != nil && firstErr1 == nil {
                firstErr1 = err
                cancel1()
            }
        }
        close(done1)
    }()

    <-done1
    cancel1()
    if firstErr1 != nil {
        fmt.Println("Error:", firstErr1)
    } else {
        fmt.Println("All fetches succeeded!")
    }

    // Example 2: One fails, cancels others
    fmt.Println("\n=== One URL fails (cancels others) ===")
    ctx2, cancel2 := context.WithCancel(context.Background())
    var firstErr2 error
    done2 := make(chan struct{})

    go func() {
        type fetch struct {
            url  string
            fail bool
        }
        fetches := []fetch{
            {"good1.com", false},
            {"bad.com", true},  // This will fail
            {"good2.com", false},
        }
        errs := make(chan error, len(fetches))

        for _, f := range fetches {
            f := f
            go func() {
                errs <- fetchURL(ctx2, f.url, f.fail)
            }()
        }

        for range fetches {
            if err := <-errs; err != nil && firstErr2 == nil && !errors.Is(err, context.Canceled) {
                firstErr2 = err
                cancel2()
            }
        }
        close(done2)
    }()

    <-done2
    cancel2()
    if firstErr2 != nil {
        fmt.Println("Error:", firstErr2)
    } else {
        fmt.Println("All fetches succeeded!")
    }
}

