import (
    "context"
    "fmt"
    "time"
)

// orDone wraps a channel to respect context cancellation
func orDone(ctx context.Context, c <-chan int) <-chan int {
    out := make(chan int)
    go func() {
        defer close(out)
        for {
            select {
            case <-ctx.Done():
                return
            case v, ok := <-c:
                if !ok {
                    return
                }
                select {
                case out <- v:
                case <-ctx.Done():
                    return
                }
            }
        }
    }()
    return out
}

func main() {
    // Source channel that produces values slowly
    source := make(chan int)
    go func() {
        defer close(source)
        for i := 1; i <= 10; i++ {
            source <- i
            time.Sleep(50 * time.Millisecond)
        }
    }()

    // Cancel after 175ms (should get ~3 values)
    ctx, cancel := context.WithTimeout(context.Background(), 175*time.Millisecond)
    defer cancel()

    // Read with cancellation support
    fmt.Println("Reading with 175ms timeout:")
    for v := range orDone(ctx, source) {
        fmt.Println("Received:", v)
    }
    fmt.Println("Done (cancelled or source closed)")
}

