import (
    "context"
    "fmt"
    "sync"
)

// tee splits one channel into two
func tee(ctx context.Context, in <-chan int) (<-chan int, <-chan int) {
    out1 := make(chan int)
    out2 := make(chan int)

    go func() {
        defer close(out1)
        defer close(out2)

        for v := range in {
            // Send to both (must send to both or neither)
            var o1, o2 = out1, out2
            for i := 0; i < 2; i++ {
                select {
                case o1 <- v:
                    o1 = nil // Disable this case
                case o2 <- v:
                    o2 = nil
                case <-ctx.Done():
                    return
                }
            }
        }
    }()

    return out1, out2
}

func main() {
    ctx := context.Background()

    // Source
    source := make(chan int)
    go func() {
        defer close(source)
        for i := 1; i <= 5; i++ {
            source <- i
        }
    }()

    // Split into two streams
    stream1, stream2 := tee(ctx, source)

    var wg sync.WaitGroup

    // Consumer 1: doubles values
    wg.Add(1)
    go func() {
        defer wg.Done()
        fmt.Println("Consumer 1 (double):")
        for v := range stream1 {
            fmt.Printf("  %d -> %d\n", v, v*2)
        }
    }()

    // Consumer 2: squares values
    wg.Add(1)
    go func() {
        defer wg.Done()
        fmt.Println("Consumer 2 (square):")
        for v := range stream2 {
            fmt.Printf("  %d -> %d\n", v, v*v)
        }
    }()

    wg.Wait()
}

