func appendLog(filename, message string) error {
    // O_APPEND: add to end
    // O_CREATE: create if doesn't exist
    // O_WRONLY: write only
    file, err := os.OpenFile(
        filename,
        os.O_APPEND|os.O_CREATE|os.O_WRONLY,
        0644,
