import (
    "fmt"
    "io"
    "strings"
)

func main() {
    // ReadAll: read everything into []byte
    reader := strings.NewReader("Hello, World!")
    data, err := io.ReadAll(reader)
    if err == nil {
        fmt.Println("ReadAll:", string(data))
    }

    // LimitReader: read at most N bytes
    reader = strings.NewReader("Hello, World!")
    limited := io.LimitReader(reader, 5)
    data, _ = io.ReadAll(limited)
    fmt.Println("LimitReader(5):", string(data))

    // MultiReader: concatenate readers
    r1 := strings.NewReader("Hello, ")
    r2 := strings.NewReader("World")
    r3 := strings.NewReader("!")
    combined := io.MultiReader(r1, r2, r3)
    data, _ = io.ReadAll(combined)
    fmt.Println("MultiReader:", string(data))

    // TeeReader: read while copying to another writer
    reader = strings.NewReader("Secret message")
    var logged strings.Builder
    tee := io.TeeReader(reader, &logged)

    // Reading from tee also writes to logged
    data, _ = io.ReadAll(tee)
    fmt.Println("TeeReader read:", string(data))
    fmt.Println("TeeReader logged:", logged.String())
}

