// Webhook with type-dependent payload
type Webhook struct {
    Type    string          `json:"type"`
    Payload json.RawMessage `json:"payload"`
}

// Different payload types
type UserCreated struct {
    UserID int    `json:"user_id"`
    Email  string `json:"email"`
}

type OrderPlaced struct {
    OrderID int     `json:"order_id"`
    Total   float64 `json:"total"`
}

func processWebhook(data []byte) {
    var webhook Webhook
    json.Unmarshal(data, &webhook)

    fmt.Printf("Webhook type: %s\n", webhook.Type)

    // Parse payload based on type
    switch webhook.Type {
    case "user.created":
        var payload UserCreated
        json.Unmarshal(webhook.Payload, &payload)
        fmt.Printf("  New user: ID=%d, Email=%s\n", payload.UserID, payload.Email)

    case "order.placed":
        var payload OrderPlaced
        json.Unmarshal(webhook.Payload, &payload)
        fmt.Printf("  New order: ID=%d, Total=$%.2f\n", payload.OrderID, payload.Total)
    }
}

