    webhooks := [][]byte{
        []byte(`{"type": "user.created", "payload": {"user_id": 42, "email": "new@example.com"}}`),
        []byte(`{"type": "order.placed", "payload": {"order_id": 1001, "total": 99.99}}`),
    }

    for _, data := range webhooks {
        processWebhook(data)
    }
}

