import (
    "encoding/json"
    "fmt"
    "strings"
    "time"
)

// Custom date type with YYYY-MM-DD format
type Date struct {
    time.Time
}

const dateFormat = "2006-01-02"

func (d Date) MarshalJSON() ([]byte, error) {
    return json.Marshal(d.Format(dateFormat))
}

func (d *Date) UnmarshalJSON(data []byte) error {
    var s string
    if err := json.Unmarshal(data, &s); err != nil {
        return err
    }
    t, err := time.Parse(dateFormat, s)
    if err != nil {
        return err
    }
    d.Time = t
    return nil
}

// Enum type with string representation
type Status int

const (
    StatusPending Status = iota
    StatusActive
    StatusCompleted
)

var statusNames = []string{"pending", "active", "completed"}

func (s Status) MarshalJSON() ([]byte, error) {
    return json.Marshal(statusNames[s])
}

func (s *Status) UnmarshalJSON(data []byte) error {
    var name string
    if err := json.Unmarshal(data, &name); err != nil {
        return err
    }
    for i, n := range statusNames {
        if strings.EqualFold(n, name) {
            *s = Status(i)
            return nil
        }
    }
    return fmt.Errorf("unknown status: %s", name)
}

type Task struct {
    Title   string `json:"title"`
    DueDate Date   `json:"due_date"`
    Status  Status `json:"status"`
}

func main() {
    task := Task{
        Title:   "Finish report",
        DueDate: Date{time.Date(2024, 12, 31, 0, 0, 0, 0, time.UTC)},
        Status:  StatusActive,
    }

    // Encode
    jsonBytes, _ := json.MarshalIndent(task, "", "  ")
    fmt.Println("Encoded:")
    fmt.Println(string(jsonBytes))

    // Decode
    input := []byte(`{"title": "Review code", "due_date": "2024-06-15", "status": "pending"}`)
    var decoded Task
    json.Unmarshal(input, &decoded)

    fmt.Println("\nDecoded:")
    fmt.Printf("Title: %s\n", decoded.Title)
    fmt.Printf("Due: %s\n", decoded.DueDate.Format(dateFormat))
    fmt.Printf("Status: %s\n", statusNames[decoded.Status])
}

