    "encoding/json"
    "fmt"
    "strings"
)

type LogEntry struct {
    Timestamp string `json:"ts"`
    Level     string `json:"level"`
    Message   string `json:"msg"`
}

func main() {
    // Encode multiple objects to a stream
    var buf bytes.Buffer
    encoder := json.NewEncoder(&buf)

    entries := []LogEntry{
        {"2024-01-15T10:30:00Z", "INFO", "Server started"},
        {"2024-01-15T10:30:05Z", "DEBUG", "Connection established"},
        {"2024-01-15T10:30:10Z", "ERROR", "Database timeout"},
    }

    for _, entry := range entries {
        encoder.Encode(entry) // Each call writes one JSON object + newline
    }

    fmt.Println("Encoded stream (NDJSON):")
    fmt.Println(buf.String())

    // Decode stream of JSON objects
    jsonStream := `{"ts":"10:30:00","level":"INFO","msg":"Request received"}
{"ts":"10:30:01","level":"INFO","msg":"Processing"}
{"ts":"10:30:02","level":"INFO","msg":"Complete"}`

    decoder := json.NewDecoder(strings.NewReader(jsonStream))

    fmt.Println("Decoded entries:")
    for decoder.More() {
        var entry LogEntry
        if err := decoder.Decode(&entry); err != nil {
            fmt.Println("Error:", err)
            break
        }
        fmt.Printf("  [%s] %s: %s\n", entry.Timestamp, entry.Level, entry.Message)
    }
}

