import (
    "context"
    "fmt"
    "io"
    "net/http"
    "time"
)

func fetchURL(ctx context.Context, url string) ([]byte, error) {
    req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
    if err != nil {
        return nil, err
    }

    client := &http.Client{}
    resp, err := client.Do(req)
    if err != nil {
        return nil, err
    }
    defer resp.Body.Close()

    return io.ReadAll(resp.Body)
}

func main() {
    // Example 1: Timeout
    fmt.Println("=== With 2s timeout (endpoint delays 5s) ===")
    ctx1, cancel1 := context.WithTimeout(context.Background(), 2*time.Second)
    defer cancel1()

    _, err := fetchURL(ctx1, "https://httpbin.org/delay/5")
    if err != nil {
        fmt.Println("Expected timeout:", err)
    }

    // Example 2: Manual cancellation
    fmt.Println("\n=== Manual cancellation ===")
    ctx2, cancel2 := context.WithCancel(context.Background())

    // Cancel after 1 second in a goroutine
    go func() {
        time.Sleep(1 * time.Second)
        fmt.Println("Cancelling request...")
        cancel2()
    }()

    _, err = fetchURL(ctx2, "https://httpbin.org/delay/10")
    if err != nil {
        fmt.Println("Cancelled:", err)
    }

    // Example 3: Success
    fmt.Println("\n=== Successful request ===")
    ctx3, cancel3 := context.WithTimeout(context.Background(), 10*time.Second)
    defer cancel3()

    body, err := fetchURL(ctx3, "https://httpbin.org/get")
    if err != nil {
        fmt.Println("Error:", err)
        return
    }
    fmt.Printf("Success! Got %d bytes\n", len(body))
}

