import (
    "bytes"
    "context"
    "fmt"
    "io"
    "net/http"
    "time"
)

func makeRequest(method, url string, body []byte) (int, []byte, error) {
    ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
    defer cancel()

    var bodyReader io.Reader
    if body != nil {
        bodyReader = bytes.NewReader(body)
    }

    req, err := http.NewRequestWithContext(ctx, method, url, bodyReader)
    if err != nil {
        return 0, nil, err
    }

    if body != nil {
        req.Header.Set("Content-Type", "application/json")
    }

    client := &http.Client{}
    resp, err := client.Do(req)
    if err != nil {
        return 0, nil, err
    }
    defer resp.Body.Close()

    respBody, _ := io.ReadAll(resp.Body)
    return resp.StatusCode, respBody, nil
}

func main() {
    baseURL := "https://httpbin.org"

    status, _, _ := makeRequest(http.MethodGet, baseURL+"/get", nil)
    fmt.Println("GET:", status)

    status, _, _ = makeRequest(http.MethodPost, baseURL+"/post", []byte(`{"name":"test"}`))
    fmt.Println("POST:", status)

    status, _, _ = makeRequest(http.MethodPut, baseURL+"/put", []byte(`{"id":1}`))
    fmt.Println("PUT:", status)

    status, _, _ = makeRequest(http.MethodDelete, baseURL+"/delete", nil)
    fmt.Println("DELETE:", status)

    status, _, _ = makeRequest(http.MethodPatch, baseURL+"/patch", []byte(`{"field":"value"}`))
    fmt.Println("PATCH:", status)
}

