import (
    "crypto/tls"
    "fmt"
    "io"
    "net"
    "net/http"
    "time"
)

func NewProductionClient() *http.Client {
    transport := &http.Transport{
        // Connection pooling
        MaxIdleConns:        100,              // Total idle connections
        MaxIdleConnsPerHost: 10,               // Per-host idle connections
        MaxConnsPerHost:     100,              // Max connections per host
        IdleConnTimeout:     90 * time.Second, // Close idle connections after

        // Connection timeouts
        DialContext: (&net.Dialer{
            Timeout:   30 * time.Second, // Connection timeout
            KeepAlive: 30 * time.Second, // Keep-alive interval
        }).DialContext,

        // TLS settings
        TLSHandshakeTimeout: 10 * time.Second,
        TLSClientConfig: &tls.Config{
            MinVersion: tls.VersionTLS12,
        },

        // Response timeouts
        ResponseHeaderTimeout: 10 * time.Second,
        ExpectContinueTimeout: 1 * time.Second,
    }

    return &http.Client{
        Transport: transport,
        Timeout:   30 * time.Second, // Overall request timeout
    }
}

func main() {
    client := NewProductionClient()

    // Make several requests (connection reuse)
    for i := 1; i <= 3; i++ {
        resp, err := client.Get("https://httpbin.org/get")
        if err != nil {
            fmt.Printf("Request %d failed: %v\n", i, err)
            continue
        }
        body, _ := io.ReadAll(resp.Body)
        resp.Body.Close()
        fmt.Printf("Request %d: %d bytes\n", i, len(body))
    }
}

package main

import (
    "context"
    "encoding/json"
    "fmt"
    "net/http"
    "time"
)

// API response types
type User struct {
    Login     string `json:"login"`
    Name      string `json:"name"`
    Company   string `json:"company"`
    Followers int    `json:"followers"`
    Repos     int    `json:"public_repos"`
}

// APIClient wraps http.Client with API-specific logic
type APIClient struct {
    client  *http.Client
    baseURL string
    token   string
}

func NewAPIClient(baseURL string, token string) *APIClient {
    return &APIClient{
        client: &http.Client{
            Timeout: 30 * time.Second,
        },
        baseURL: baseURL,
        token:   token,
    }
}

func (c *APIClient) do(ctx context.Context, method, path string, result any) error {
    req, err := http.NewRequestWithContext(ctx, method, c.baseURL+path, nil)
    if err != nil {
        return fmt.Errorf("create request: %w", err)
    }

    req.Header.Set("Accept", "application/json")
    req.Header.Set("User-Agent", "GoTutorial/1.0")
    if c.token != "" {
        req.Header.Set("Authorization", "Bearer "+c.token)
    }

    resp, err := c.client.Do(req)
    if err != nil {
        return fmt.Errorf("execute request: %w", err)
    }
    defer resp.Body.Close()

    if resp.StatusCode < 200 || resp.StatusCode >= 300 {
        return fmt.Errorf("unexpected status: %s", resp.Status)
    }

    if result != nil {
        if err := json.NewDecoder(resp.Body).Decode(result); err != nil {
            return fmt.Errorf("decode response: %w", err)
        }
    }

    return nil
}

// Typed API methods
func (c *APIClient) GetUser(ctx context.Context, username string) (*User, error) {
    var user User
    err := c.do(ctx, http.MethodGet, "/users/"+username, &user)
    if err != nil {
        return nil, err
    }
    return &user, nil
}

func main() {
    client := NewAPIClient("https://api.github.com", "")

    ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
    defer cancel()

    user, err := client.GetUser(ctx, "golang")
    if err != nil {
        fmt.Println("Error:", err)
        return
    }

    fmt.Println("User:", user.Login)
    fmt.Println("Name:", user.Name)
