import (
    "context"
    "fmt"
    "io"
    "math"
    "net/http"
    "time"
)

func fetchWithRetry(ctx context.Context, url string, maxRetries int) ([]byte, error) {
    client := &http.Client{Timeout: 10 * time.Second}

    var lastErr error
    for attempt := 0; attempt <= maxRetries; attempt++ {
        if attempt > 0 {
            // Exponential backoff: 1s, 2s, 4s...
            delay := time.Duration(math.Pow(2, float64(attempt-1))) * time.Second
            fmt.Printf("Attempt %d failed, retrying in %v...\n", attempt, delay)

            select {
            case <-time.After(delay):
            case <-ctx.Done():
                return nil, ctx.Err()
            }
        }

        req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
        if err != nil {
            return nil, err
        }

        resp, err := client.Do(req)
        if err != nil {
            lastErr = err
            continue // Retry on network error
        }
        defer resp.Body.Close()

        // Retry on 5xx errors
        if resp.StatusCode >= 500 {
            lastErr = fmt.Errorf("server error: %s", resp.Status)
            continue
        }

        // Don't retry on 4xx errors
        if resp.StatusCode >= 400 {
            return nil, fmt.Errorf("client error: %s", resp.Status)
        }

        return io.ReadAll(resp.Body)
    }

    return nil, fmt.Errorf("max retries exceeded: %w", lastErr)
}

func main() {
    ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
    defer cancel()

    // This will succeed
    body, err := fetchWithRetry(ctx, "https://httpbin.org/get", 3)
    if err != nil {
        fmt.Println("Error:", err)
        return
    }
    fmt.Printf("Success: got %d bytes\n", len(body))
}

