import (
    "database/sql"
    "fmt"
    "log"

    _ "github.com/mattn/go-sqlite3"
)

func transferFunds(db *sql.DB, fromID, toID int, amount float64) error {
    tx, err := db.Begin()
    if err != nil {
        return err
    }
    defer tx.Rollback() // Safe to call after Commit

    // Check source balance
    var balance float64
    err = tx.QueryRow("SELECT balance FROM accounts WHERE id = ?", fromID).Scan(&balance)
    if err != nil {
        return fmt.Errorf("source account: %w", err)
    }
    if balance < amount {
        return fmt.Errorf("insufficient funds: have %.2f, need %.2f", balance, amount)
    }

    // Deduct from source
    _, err = tx.Exec("UPDATE accounts SET balance = balance - ? WHERE id = ?", amount, fromID)
    if err != nil {
        return err
    }

    // Add to destination
    _, err = tx.Exec("UPDATE accounts SET balance = balance + ? WHERE id = ?", amount, toID)
    if err != nil {
        return err
    }

    return tx.Commit()
}

func main() {
    db, _ := sql.Open("sqlite3", ":memory:")
    defer db.Close()

    // Setup
    db.Exec(`CREATE TABLE accounts (id INTEGER PRIMARY KEY, name TEXT, balance REAL)`)
    db.Exec(`INSERT INTO accounts (name, balance) VALUES ('Alice', 100.00)`)
    db.Exec(`INSERT INTO accounts (name, balance) VALUES ('Bob', 50.00)`)

    fmt.Println("Before transfer:")
    printBalances(db)

    // Successful transfer
    err := transferFunds(db, 1, 2, 30.00)
    if err != nil {
        log.Fatal(err)
    }
    fmt.Println("\nAfter transfer of $30:")
    printBalances(db)

    // Failed transfer (insufficient funds)
    err = transferFunds(db, 1, 2, 1000.00)
    fmt.Println("\nTransfer $1000:", err)
    fmt.Println("Balances unchanged:")
    printBalances(db)
}

func printBalances(db *sql.DB) {
    rows, _ := db.Query("SELECT name, balance FROM accounts")
    defer rows.Close()
    for rows.Next() {
        var name string
        var balance float64
        rows.Scan(&name, &balance)
        fmt.Printf("  %s: $%.2f\n", name, balance)
    }
}

