func queryWithTimeout(db *sql.DB, timeout time.Duration) ([]string, error) {
    ctx, cancel := context.WithTimeout(context.Background(), timeout)
    defer cancel()

    rows, err := db.QueryContext(ctx, "SELECT name FROM users")
    if err != nil {
        return nil, err
    }
    defer rows.Close()

    var names []string
    for rows.Next() {
        var name string
        if err := rows.Scan(&name); err != nil {
            return nil, err
        }
        names = append(names, name)
    }

    return names, rows.Err()
}

func insertWithContext(ctx context.Context, db *sql.DB, name string) error {
    _, err := db.ExecContext(ctx, "INSERT INTO users (name) VALUES (?)", name)
    return err
}

func main() {
    db, _ := sql.Open("sqlite3", ":memory:")
    defer db.Close()

    db.Exec(`CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT)`)
    db.Exec(`INSERT INTO users (name) VALUES ('Alice')`)
    db.Exec(`INSERT INTO users (name) VALUES ('Bob')`)

    // Query with timeout
    names, err := queryWithTimeout(db, 5*time.Second)
    if err != nil {
        fmt.Println("Query error:", err)
        return
    }
    fmt.Println("Users:", names)

    // Insert with cancellable context
    ctx, cancel := context.WithCancel(context.Background())
    defer cancel()

    err = insertWithContext(ctx, db, "Carol")
    if err != nil {
        fmt.Println("Insert error:", err)
        return
    }

