import (
    "context"
    "database/sql"
    "errors"
    "fmt"
    "time"

    _ "github.com/mattn/go-sqlite3"
)

var ErrNotFound = errors.New("not found")

type User struct {
    ID        int64
    Email     string
    Name      string
    CreatedAt time.Time
}

type UserRepository struct {
    db *sql.DB
}

func NewUserRepository(db *sql.DB) *UserRepository {
    return &UserRepository{db: db}
}

func (r *UserRepository) FindByID(ctx context.Context, id int64) (User, error) {
    var u User
    err := r.db.QueryRowContext(ctx,
        "SELECT id, email, name, created_at FROM users WHERE id = ?", id,
    ).Scan(&u.ID, &u.Email, &u.Name, &u.CreatedAt)

    if errors.Is(err, sql.ErrNoRows) {
        return User{}, ErrNotFound
    }
    return u, err
}

func (r *UserRepository) Create(ctx context.Context, email, name string) (User, error) {
    now := time.Now()
    result, err := r.db.ExecContext(ctx,
        "INSERT INTO users (email, name, created_at) VALUES (?, ?, ?)",
        email, name, now,
    )
    if err != nil {
        return User{}, err
    }

    id, _ := result.LastInsertId()
    return User{ID: id, Email: email, Name: name, CreatedAt: now}, nil
}

func (r *UserRepository) Delete(ctx context.Context, id int64) error {
    result, err := r.db.ExecContext(ctx, "DELETE FROM users WHERE id = ?", id)
    if err != nil {
        return err
    }

    affected, _ := result.RowsAffected()
    if affected == 0 {
        return ErrNotFound
    }
    return nil
}

func main() {
    db, _ := sql.Open("sqlite3", ":memory:")
    defer db.Close()

    db.Exec(`CREATE TABLE users (
        id INTEGER PRIMARY KEY,
        email TEXT UNIQUE,
        name TEXT,
        created_at DATETIME
    )`)

    repo := NewUserRepository(db)
    ctx := context.Background()

    // Create
    user, err := repo.Create(ctx, "alice@example.com", "Alice")
    if err != nil {
        fmt.Println("Create error:", err)
        return
    }
    fmt.Printf("Created: %+v\n", user)

    // Find
    found, err := repo.FindByID(ctx, user.ID)
    if err != nil {
        fmt.Println("Find error:", err)
        return
    }
    fmt.Printf("Found: %+v\n", found)

    // Delete
    err = repo.Delete(ctx, user.ID)
    if err != nil {
        fmt.Println("Delete error:", err)
        return
    }
    fmt.Println("Deleted successfully")

    // Find deleted (should fail)
    _, err = repo.FindByID(ctx, user.ID)
    if errors.Is(err, ErrNotFound) {
        fmt.Println("Confirmed: user not found after delete")
    }
}

