func TestParallel(t *testing.T) {
    tests := []struct {
        name  string
        input int
        want  int
    }{
        {"double 1", 1, 2},
        {"double 2", 2, 4},
        {"double 3", 3, 6},
        {"double 4", 4, 8},
    }

    for _, tt := range tests {
        tt := tt // Capture range variable!
        t.Run(tt.name, func(t *testing.T) {
            t.Parallel() // Mark as parallel

            got := slowOperation(tt.input)
            if got != tt.want {
                t.Errorf("slowOperation(%d) = %d; want %d",
                    tt.input, got, tt.want)
            }
        })
    }
    // All 4 subtests run concurrently, taking ~100ms total instead of ~400ms
}

