var ErrInvalidInput = errors.New("invalid input")

func ValidateAge(age int) error {
    if age < 0 {
        return fmt.Errorf("%w: age cannot be negative", ErrInvalidInput)
    }
    if age > 150 {
        return fmt.Errorf("%w: age too large", ErrInvalidInput)
    }
    return nil
}

func TestValidateAge(t *testing.T) {
    tests := []struct {
        name        string
        age         int
        wantErr     bool
        errContains string // Optional: check error message
    }{
        {"valid age", 25, false, ""},
        {"zero age", 0, false, ""},
        {"max valid", 150, false, ""},
        {"negative", -1, true, "negative"},
        {"too large", 200, true, "too large"},
    }

    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            err := ValidateAge(tt.age)

            if (err != nil) != tt.wantErr {
                t.Fatalf("ValidateAge(%d) error = %v, wantErr %v",
                    tt.age, err, tt.wantErr)
            }

            // Check error type
            if tt.wantErr && !errors.Is(err, ErrInvalidInput) {
                t.Errorf("error should wrap ErrInvalidInput")
            }

            // Check error message contains expected text
            if tt.errContains != "" && !strings.Contains(err.Error(), tt.errContains) {
                t.Errorf("error %q should contain %q", err, tt.errContains)
            }
        })
    }
}

