)

func BenchmarkSortInts(b *testing.B) {
    // Setup: create random data
    data := make([]int, 10000)
    for i := range data {
        data[i] = rand.Intn(10000)
    }

    b.ResetTimer() // Exclude setup from timing

    for i := 0; i < b.N; i++ {
        // Stop timer for per-iteration setup
        b.StopTimer()
        dataCopy := make([]int, len(data))
        copy(dataCopy, data)
        b.StartTimer()

        sort.Ints(dataCopy)
    }
}

// Alternative: pre-generate all copies
func BenchmarkSortIntsPregen(b *testing.B) {
    // Pre-generate N copies
    data := make([][]int, b.N)
    for i := range data {
        data[i] = make([]int, 1000)
        for j := range data[i] {
            data[i][j] = rand.Intn(1000)
        }
    }

    b.ResetTimer()

    for i := 0; i < b.N; i++ {
        sort.Ints(data[i])
    }
}

