import "fmt"

// [T any] means T can be any type
func PrintSlice[T any](items []T) {
    for i, item := range items {
        fmt.Printf("  [%d]: %v\n", i, item)
    }
}

func First[T any](items []T) (T, bool) {
    if len(items) == 0 {
        var zero T  // Zero value of T
        return zero, false
    }
    return items[0], true
}

func Last[T any](items []T) (T, bool) {
    if len(items) == 0 {
        var zero T
        return zero, false
    }
    return items[len(items)-1], true
}

func main() {
    nums := []int{10, 20, 30}
    names := []string{"Alice", "Bob"}

    fmt.Println("Numbers:")
    PrintSlice(nums)  // T inferred as int

    fmt.Println("Names:")
    PrintSlice(names) // T inferred as string

    if first, ok := First(nums); ok {
        fmt.Println("First:", first)
    }
    if last, ok := Last(names); ok {
        fmt.Println("Last:", last)
    }
}

