import "fmt"

// Union of numeric types
type Number interface {
    int | int32 | int64 | float32 | float64
}

func Sum[T Number](nums []T) T {
    var total T
    for _, n := range nums {
        total += n  // + allowed because Number types support it
    }
    return total
}

// Ordered constraint for comparison
type Ordered interface {
    int | int64 | float64 | string
}

func Min[T Ordered](a, b T) T {
    if a < b {  // < allowed because Ordered types support it
        return a
    }
    return b
}

func Max[T Ordered](a, b T) T {
    if a > b {
        return a
    }
    return b
}

func main() {
