import "fmt"

type Stack[T any] struct {
    items []T
}

func (s *Stack[T]) Push(item T) {
    s.items = append(s.items, item)
}

func (s *Stack[T]) Pop() (T, bool) {
    if len(s.items) == 0 {
        var zero T
        return zero, false
    }
    idx := len(s.items) - 1
    item := s.items[idx]
    s.items = s.items[:idx]
    return item, true
}

func (s *Stack[T]) Peek() (T, bool) {
    if len(s.items) == 0 {
        var zero T
        return zero, false
    }
    return s.items[len(s.items)-1], true
}

func (s *Stack[T]) Len() int {
    return len(s.items)
}

func main() {
    // Stack of integers
    intStack := &Stack[int]{}
    intStack.Push(10)
    intStack.Push(20)
    intStack.Push(30)

    fmt.Println("Length:", intStack.Len())
    if val, ok := intStack.Pop(); ok {
        fmt.Println("Popped:", val)
    }

    // Stack of strings
    strStack := &Stack[string]{}
    strStack.Push("first")
    strStack.Push("second")

    if val, ok := strStack.Peek(); ok {
        fmt.Println("Top:", val)
    }
}

