import "fmt"

// Contains checks if item exists in slice
func Contains[T comparable](items []T, target T) bool {
    for _, item := range items {
        if item == target {  // == requires comparable
            return true
        }
    }
    return false
}

// IndexOf returns index of first match, or -1
func IndexOf[T comparable](items []T, target T) int {
    for i, item := range items {
        if item == target {
            return i
        }
    }
    return -1
}

// Unique removes duplicates
func Unique[T comparable](items []T) []T {
    seen := make(map[T]bool)
    var result []T
    for _, item := range items {
        if !seen[item] {
            seen[item] = true
            result = append(result, item)
        }
    }
    return result
}

func main() {
    nums := []int{1, 2, 3, 2, 1, 4}
    fmt.Println("Contains 3:", Contains(nums, 3))
    fmt.Println("Index of 2:", IndexOf(nums, 2))
    fmt.Println("Unique:", Unique(nums))

    names := []string{"a", "b", "a", "c"}
    fmt.Println("Unique names:", Unique(names))
}

