import (
	"fmt"
	"sync"
	"time"
)

type PubSub struct {
	mu   sync.RWMutex
	subs []chan string
}

func (ps *PubSub) Subscribe() <-chan string {
	ps.mu.Lock()
	defer ps.mu.Unlock()
	ch := make(chan string, 10) // Buffered: subscriber won't block publisher
	ps.subs = append(ps.subs, ch)
	return ch
}

func (ps *PubSub) Publish(msg string) {
	ps.mu.RLock()
	defer ps.mu.RUnlock()
	for _, ch := range ps.subs {
		ch <- msg
	}
}

func (ps *PubSub) Close() {
	ps.mu.Lock()
	defer ps.mu.Unlock()
	for _, ch := range ps.subs {
		close(ch)
	}
}

func main() {
	ps := &PubSub{}

	// Create 3 subscribers
	var wg sync.WaitGroup
	for i := 1; i <= 3; i++ {
		wg.Add(1)
		ch := ps.Subscribe()
		go func(id int, ch <-chan string) {
			defer wg.Done()
			for msg := range ch {
				fmt.Printf("Subscriber %d received: %s\n", id, msg)
			}
		}(i, ch)
	}

	// Publish events
	time.Sleep(10 * time.Millisecond) // Let subscribers start
	ps.Publish("event-1")
	ps.Publish("event-2")

	time.Sleep(10 * time.Millisecond) // Let messages deliver
	ps.Close()
	wg.Wait()
	fmt.Println("All subscribers done")
}

