// Cache with RWMutex: many readers, occasional writes
type Cache struct {
	mu   sync.RWMutex
	data map[string]string
}

func NewCache() *Cache {
	return &Cache{data: make(map[string]string)}
}

// Get uses RLock: multiple goroutines can read simultaneously
func (c *Cache) Get(key string) (string, bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()
	val, ok := c.data[key]
	return val, ok
}

// Set uses Lock: exclusive access for writing
func (c *Cache) Set(key, value string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.data[key] = value
}

func main() {
	cache := NewCache()
	cache.Set("name", "Alice")

	var wg sync.WaitGroup

	// 10 readers can run concurrently
	for i := 0; i < 10; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			if val, ok := cache.Get("name"); ok {
				fmt.Printf("Reader %d: %s\n", id, val)
			}
		}(i)
	}

	wg.Wait()
}

