type UserService struct {
	db *sql.DB
}

func (s *UserService) GetUser(ctx context.Context, id string) (*User, error) {
	// QueryRowContext stops if ctx is cancelled
	row := s.db.QueryRowContext(ctx,
		"SELECT id, name, email FROM users WHERE id = $1", id)

	var user User
	err := row.Scan(&user.ID, &user.Name, &user.Email)
	return &user, err
}

func (s *UserService) GetUserHandler(w http.ResponseWriter, r *http.Request) {
	// Step 1: Get context from request
	// This is cancelled if the client closes their browser
	ctx := r.Context()

	// Step 2: Add our own timeout (5 seconds max)
	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()

	// Step 3: Pass context to database call
	user, err := s.GetUser(ctx, r.URL.Query().Get("id"))
	if err != nil {
		if ctx.Err() == context.Canceled {
			// Client disconnected, no point sending response
			return
		}
		http.Error(w, err.Error(), 500)
		return
	}

	json.NewEncoder(w).Encode(user)
}

// Pattern: ctx is always the first parameter
func (s *Service) ProcessOrder(ctx context.Context, orderID string) error {
	// Pass context to all downstream calls
	order, err := s.db.GetOrder(ctx, orderID)
	if err != nil {
		return err
	}

	// Pass context to external API call
	payment, err := s.paymentClient.Charge(ctx, order.Amount)
	if err != nil {
		return err
	}

	// Pass context when spawning goroutines
	go s.sendConfirmationEmail(ctx, order, payment)

	return s.db.UpdateOrderStatus(ctx, orderID, "completed")
}

