import (
	"fmt"
	"sync/atomic"
)

func main() {
	var counter int64 = 10

	// Add: atomically add delta, returns new value
	newVal := atomic.AddInt64(&counter, 5)
	fmt.Println("After Add(5):", newVal) // 15

	// Load: atomically read the value
	current := atomic.LoadInt64(&counter)
	fmt.Println("Load:", current) // 15

	// Store: atomically write a new value
	atomic.StoreInt64(&counter, 100)
	fmt.Println("After Store(100):", atomic.LoadInt64(&counter)) // 100

	// Swap: atomically replace and get old value
	old := atomic.SwapInt64(&counter, 200)
	fmt.Println("Swap returned:", old)                    // 100
	fmt.Println("New value:", atomic.LoadInt64(&counter)) // 200

	// CompareAndSwap: replace if current equals expected
	// Only succeeds if counter is currently 200
	swapped := atomic.CompareAndSwapInt64(&counter, 200, 300)
	fmt.Println("CAS succeeded:", swapped)            // true
	fmt.Println("Value:", atomic.LoadInt64(&counter)) // 300

	// CAS fails if value changed
	swapped = atomic.CompareAndSwapInt64(&counter, 999, 400)
	fmt.Println("CAS with wrong expected:", swapped)            // false
	fmt.Println("Value unchanged:", atomic.LoadInt64(&counter)) // 300
}

