import (
	"fmt"
	"sync/atomic"
)

func main() {
	// Declare an atomic counter (starts at 0)
	var counter atomic.Int64

	// Store: set the value to 10
	counter.Store(10)

	// Load: read the current value
	fmt.Println("Initial:", counter.Load()) // 10

	// Add: increase by 5, get the new value back
	newVal := counter.Add(5)
	fmt.Println("After Add(5):", newVal) // 15

	// Swap: set to 100, get the old value back
	old := counter.Swap(100)
	fmt.Println("Swap returned:", old) // 15 (the old value)

	// CompareAndSwap: only update if current value is 100
	// Returns true if it worked, false if value was different
	swapped := counter.CompareAndSwap(100, 200)
	fmt.Println("CAS:", swapped, counter.Load()) // true 200

	// atomic.Bool: perfect for on/off flags
	var running atomic.Bool
	running.Store(true)
	fmt.Println("Running:", running.Load()) // true

	// atomic.Pointer[T]: swap entire structs safely
	type Config struct {
		Host string
		Port int
	}

	// Store initial config
	var currentConfig atomic.Pointer[Config]
	currentConfig.Store(&Config{Host: "localhost", Port: 8080})

	// Any goroutine can read the current config
	cfg := currentConfig.Load()
	fmt.Printf("Config: %s:%d\n", cfg.Host, cfg.Port)

	// Swap to new config, get old config back
	// Old config stays valid for goroutines still using it
	newCfg := &Config{Host: "0.0.0.0", Port: 9000}
	oldCfg := currentConfig.Swap(newCfg)
	fmt.Printf("Old: %s:%d, New: %s:%d\n",
		oldCfg.Host, oldCfg.Port,
		currentConfig.Load().Host, currentConfig.Load().Port)
}

