	"sync"
	"sync/atomic"
)

// Metrics tracks request statistics
// All fields are atomic, so any goroutine can update them safely
type Metrics struct {
	requests atomic.Int64
	errors   atomic.Int64
	bytesIn  atomic.Int64
	bytesOut atomic.Int64
}

// RecordRequest logs a successful request with byte counts
func (m *Metrics) RecordRequest(bytesIn, bytesOut int64) {
	m.requests.Add(1)        // count this request
	m.bytesIn.Add(bytesIn)   // track incoming bytes
	m.bytesOut.Add(bytesOut) // track outgoing bytes
}

// RecordError logs a failed request
func (m *Metrics) RecordError() {
	m.requests.Add(1) // errors count as requests too
	m.errors.Add(1)   // also count the error
}

// Snapshot returns current values (for reporting)
func (m *Metrics) Snapshot() (requests, errors, bytesIn, bytesOut int64) {
	return m.requests.Load(), m.errors.Load(), m.bytesIn.Load(), m.bytesOut.Load()
}

func main() {
	var metrics Metrics
	var wg sync.WaitGroup

	// Launch 1000 goroutines at once (like 1000 users hitting your server)
	for i := 0; i < 1000; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			// Every 10th request is an error (id 0, 10, 20, ...)
			if id%10 == 0 {
				metrics.RecordError()
			} else {
				// Normal request: 100 bytes in, 500 bytes out
				metrics.RecordRequest(100, 500)
			}
		}(i)
	}

	// Wait for all requests to finish
	wg.Wait()

	// Print the final counts
	req, errs, in, out := metrics.Snapshot()
	fmt.Printf("Requests: %d, Errors: %d\n", req, errs)
	fmt.Printf("Bytes In: %d, Bytes Out: %d\n", in, out)
}

// ATOMIC: Perfect for a single counter
// Multiple goroutines can call Add() safely
var requestCount atomic.Int64

func increment() {
	requestCount.Add(1)
}

// MUTEX: Required when multiple fields must stay in sync
// The lock ensures no one reads while we're updating
type Account struct {
	mu      sync.Mutex
	balance int64
	pending int64
}

func (a *Account) Transfer(amount int64) {
	a.mu.Lock()
	defer a.mu.Unlock()
	// Inside the lock: both updates happen as one unit
	// No goroutine can see balance changed but pending unchanged
	a.balance -= amount
	a.pending += amount
}

// WRONG: Atomic on each field doesn't make the pair atomic!
type BrokenAccount struct {
	balance atomic.Int64
	pending atomic.Int64
}

func (a *BrokenAccount) Transfer(amount int64) {
	// Problem: another goroutine could read right here,
	// seeing balance decreased but pending not yet increased
	a.balance.Add(-amount)
	// The total is temporarily wrong!
	a.pending.Add(amount)
}

