import (
	"fmt"
	"sync"
	"sync/atomic"
)

// atomicMax updates the max value without locks
// Multiple goroutines can call this safely
func atomicMax(addr *atomic.Int64, val int64) {
	for {
		// Step 1: Read the current maximum
		old := addr.Load()

		// Step 2: If our value isn't larger, we're done
		if val <= old {
			return
		}

		// Step 3: Try to update (only succeeds if still equals 'old')
		if addr.CompareAndSwap(old, val) {
			return // Success! We set the new max
		}

		// Step 4: CAS failed, someone else updated it
		// Loop back and try again with the new value
	}
}

func main() {
	var maxSeen atomic.Int64
	var wg sync.WaitGroup

	// 8 goroutines race to update the maximum
	values := []int64{42, 17, 99, 3, 88, 99, 100, 50}

	for _, v := range values {
		wg.Add(1)
		go func(val int64) {
			defer wg.Done()
			atomicMax(&maxSeen, val)
		}(v)
	}

	wg.Wait()
	fmt.Println("Maximum:", maxSeen.Load())
}

