import (
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

type Worker struct {
	// atomic.Bool starts as false (keep running)
	// When set to true, workers should stop
	shutdown atomic.Bool
}

func (w *Worker) Run(id int, wg *sync.WaitGroup) {
	defer wg.Done()

	// Keep working until shutdown is true
	for !w.shutdown.Load() {
		fmt.Printf("Worker %d: processing...\n", id)
		time.Sleep(200 * time.Millisecond)
	}

	// Clean exit
	fmt.Printf("Worker %d: shutting down\n", id)
}

func (w *Worker) Stop() {
	// Set flag to true - all workers will see this
	w.shutdown.Store(true)
}

func main() {
	var wg sync.WaitGroup
	worker := &Worker{}

	// Start 3 workers sharing the same shutdown flag
	for i := 1; i <= 3; i++ {
		wg.Add(1)
		go worker.Run(i, &wg)
	}

	// Let them work for a bit
	time.Sleep(500 * time.Millisecond)

	// Tell all workers to stop
	fmt.Println("Sending shutdown signal...")
	worker.Stop()

	// Wait for all workers to finish
	wg.Wait()
	fmt.Println("All workers stopped")
}

