var (
	config     map[string]string // shared config, initially nil
	configOnce sync.Once         // ensures loadConfig runs once
)

func loadConfig() {
	fmt.Println("Loading config...")
	config = map[string]string{
		"host": "localhost",
		"port": "8080",
	}
}

func GetConfig() map[string]string {
	// Only the first call runs loadConfig
	// All other calls skip it and return immediately
	configOnce.Do(loadConfig)
	return config
}

func main() {
	var wg sync.WaitGroup

	// Start 10 goroutines that all call GetConfig at the same time
	for i := 0; i < 10; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			cfg := GetConfig()
			fmt.Printf("Goroutine %d got config: %v\n", id, cfg["host"])
		}(i)
	}

	wg.Wait()
}

