import (
	"fmt"
	"sync"
	"time"
)

type Queue struct {
	mu    sync.Mutex // protects the items slice
	cond  *sync.Cond // lets goroutines wait for items
	items []int
}

func NewQueue() *Queue {
	q := &Queue{}
	// Create a Cond that uses our mutex
	q.cond = sync.NewCond(&q.mu)
	return q
}

func (q *Queue) Put(item int) {
	q.mu.Lock()
	defer q.mu.Unlock()

	// Add item to queue
	q.items = append(q.items, item)
	fmt.Printf("Put: %d, queue: %v\n", item, q.items)

	// Wake up one goroutine waiting in Get()
	q.cond.Signal()
}

func (q *Queue) Get() int {
	q.mu.Lock()
	defer q.mu.Unlock()

	// If queue is empty, sleep until Signal() wakes us
	// Use 'for' not 'if' because we might wake up and queue is still empty
	for len(q.items) == 0 {
		q.cond.Wait() // releases lock, sleeps, reacquires lock when woken
	}

	// Take first item from queue
	item := q.items[0]
	q.items = q.items[1:]
	return item
}

func main() {
	q := NewQueue()
	var wg sync.WaitGroup

	// Start a consumer goroutine
	// It will wait for items to appear in the queue
	wg.Add(1)
	go func() {
		defer wg.Done()
		for i := 0; i < 3; i++ {
			item := q.Get() // blocks until an item is available
			fmt.Printf("Got: %d\n", item)
		}
	}()

	// Producer: add 3 items with delays
	for i := 1; i <= 3; i++ {
		time.Sleep(100 * time.Millisecond)
		q.Put(i)
	}

	wg.Wait()
}

