import (
	"fmt"
	"sync"
	"time"
)

type Barrier struct {
	mu      sync.Mutex
	cond    *sync.Cond
	count   int  // how many workers have arrived
	target  int  // how many we're waiting for
	release bool // true when all workers can proceed
}

func NewBarrier(n int) *Barrier {
	b := &Barrier{target: n}
	b.cond = sync.NewCond(&b.mu)
	return b
}

func (b *Barrier) Wait(id int) {
	b.mu.Lock()
	defer b.mu.Unlock()

	// This worker has arrived
	b.count++
	fmt.Printf("Worker %d arrived (%d/%d)\n", id, b.count, b.target)

	if b.count >= b.target {
		// Last worker to arrive: wake everyone up
		b.release = true
		b.cond.Broadcast()
	} else {
		// Not everyone is here yet, wait
		for !b.release {
			b.cond.Wait()
		}
	}

	fmt.Printf("Worker %d proceeding\n", id)
}

func main() {
	// Create a barrier that waits for 3 workers
	barrier := NewBarrier(3)
	var wg sync.WaitGroup

	// Start 3 workers, each arrives at different times
	for i := 1; i <= 3; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			// Simulate different arrival times
			time.Sleep(time.Duration(id*100) * time.Millisecond)
			barrier.Wait(id)
		}(i)
	}

	wg.Wait()
}

