import (
	"fmt"
	"sync"
)

func main() {
	var cache sync.Map // no need to initialize, zero value is ready to use

	// Store values
	// Values are stored as 'any', so no type checking at compile time
	cache.Store("name", "Alice")
	cache.Store("age", 30)
	cache.Store("city", "NYC")

	// Load a value
	// Returns (value, ok) like a regular map
	if val, ok := cache.Load("name"); ok {
		// Must use type assertion to get the actual type
		fmt.Println("Name:", val.(string))
	}

	// LoadOrStore: get existing value, or store new one if key doesn't exist
	// Returns (actual value, whether it was already there)
	actual, loaded := cache.LoadOrStore("country", "USA")
	fmt.Printf("Country: %v (was already stored: %v)\n", actual, loaded)

	// LoadAndDelete: get a value and remove it in one atomic operation
	val, loaded := cache.LoadAndDelete("age")
	if loaded {
		fmt.Println("Deleted age:", val)
	}

	// Range: loop over all key-value pairs
	fmt.Println("Remaining entries:")
	cache.Range(func(key, value any) bool {
		fmt.Printf("  %v: %v\n", key, value)
		return true // return false to stop early
	})
}

