import (
	"bytes"
	"fmt"
	"sync"
)

// Create a pool of byte buffers
// New is called when Get() finds an empty pool
var bufferPool = sync.Pool{
	New: func() any {
		fmt.Println("Allocating new buffer")
		return new(bytes.Buffer)
	},
}

func processData(data string) string {
	// Get a buffer from the pool
	// If pool is empty, New() creates one
	buf := bufferPool.Get().(*bytes.Buffer)

	// Always reset before use - buffer may have old data
	buf.Reset()

	// Use the buffer
	buf.WriteString("Processed: ")
	buf.WriteString(data)
	result := buf.String()

	// Return buffer to pool for reuse by other goroutines
	bufferPool.Put(buf)

	return result
}

func main() {
	// First call: pool is empty, so New() allocates a buffer
	fmt.Println(processData("hello"))

	// Second call: reuses the buffer we just put back
	fmt.Println(processData("world"))
}

