import (
	"bytes"
	"encoding/json"
	"net/http"
	"sync"
)

// Pool of buffers for JSON encoding
var encoderPool = sync.Pool{
	New: func() any {
		return new(bytes.Buffer)
	},
}

func handleRequest(w http.ResponseWriter, r *http.Request) {
	// Get buffer from pool (or create new if empty)
	buf := encoderPool.Get().(*bytes.Buffer)
	buf.Reset()                // clear any leftover data
	defer encoderPool.Put(buf) // return to pool when handler finishes

	response := map[string]string{"status": "ok"}

	// Encode JSON into the pooled buffer
	if err := json.NewEncoder(buf).Encode(response); err != nil {
		http.Error(w, err.Error(), 500)
		return
	}

	// Write response
	w.Header().Set("Content-Type", "application/json")
	w.Write(buf.Bytes())
}

