import (
	"context"
	"fmt"
	"sync"
	"time"

	"golang.org/x/sync/semaphore"
)

func main() {
	// Create semaphore with 3 slots
	// Only 3 workers can run at the same time
	sem := semaphore.NewWeighted(3)
	ctx := context.Background()

	var wg sync.WaitGroup

	// Start 6 workers, but only 3 can run concurrently
	for i := 1; i <= 6; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()

			// Try to acquire 1 slot (blocks if all 3 are taken)
			if err := sem.Acquire(ctx, 1); err != nil {
				return
			}

			fmt.Printf("Worker %d: started\n", id)
			time.Sleep(100 * time.Millisecond) // simulate work

			// Release the slot so another worker can start
			sem.Release(1)
			fmt.Printf("Worker %d: done\n", id)
		}(i)
	}

	wg.Wait()
}

