import (
	"fmt"
	"sync"
	"time"
)

// Job represents work to be done
type Job struct {
	ID   int
	Data string
}

// Result holds the output of a completed job
type Result struct {
	JobID  int
	Output string
	Err    error
}

// worker processes jobs until the jobs channel is closed
func worker(id int, jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
	defer wg.Done() // Signal "I'm done" when function returns

	for job := range jobs {
		fmt.Printf("Worker %d processing job %d\n", id, job.ID)
		time.Sleep(100 * time.Millisecond)
		results <- Result{
			JobID:  job.ID,
			Output: fmt.Sprintf("Processed: %s", job.Data),
		}
	}
}

func main() {
	numWorkers := 3
	numJobs := 10

	jobs := make(chan Job, numJobs)
	results := make(chan Result, numJobs)

	// 1. Start workers first
	var wg sync.WaitGroup
	for w := 1; w <= numWorkers; w++ {
		wg.Add(1)
		go worker(w, jobs, results, &wg)
	}

	// 2. Send all jobs
	for j := 1; j <= numJobs; j++ {
		jobs <- Job{ID: j, Data: fmt.Sprintf("task-%d", j)}
	}
	close(jobs) // No more jobs

	// 3. Close results after workers finish (must be in goroutine!)
	go func() {
		wg.Wait()
		close(results)
	}()

	// 4. Collect results
	for result := range results {
		fmt.Printf("Result: %s\n", result.Output)
	}
}

// WRONG: causes deadlock
close(jobs)
wg.Wait()        // Main stuck here
close(results)   // Never reached

for result := range results {
    fmt.Println(result)  // Never reached
}

