import (
	"fmt"
	"sync"
	"time"
)

// ProcessedImage holds the result of processing one image
type ProcessedImage struct {
	Path   string
	Result string
	Err    error
}

// ImageProcessor manages a pool of workers for image processing
type ImageProcessor struct {
	workers int
	jobs    chan string           // Paths to process
	results chan ProcessedImage   // Processed results
	wg      sync.WaitGroup
}

// NewImageProcessor creates and starts the worker pool
func NewImageProcessor(workers int) *ImageProcessor {
	p := &ImageProcessor{
		workers: workers,
		jobs:    make(chan string, 100),
		results: make(chan ProcessedImage, 100),
	}

	// Start the workers
	for i := 0; i < workers; i++ {
		p.wg.Add(1)
		go p.worker(i)
	}

	// Close results channel when all workers finish
	go func() {
		p.wg.Wait()
		close(p.results)
	}()

	return p
}

// worker processes images until jobs channel is closed
func (p *ImageProcessor) worker(id int) {
	defer p.wg.Done()

	for path := range p.jobs {
		result := ProcessedImage{Path: path}

		// Step 1: Load image into memory
		fmt.Printf("Worker %d: loading %s\n", id, path)
		time.Sleep(50 * time.Millisecond)

		// Step 2: Process the image
		fmt.Printf("Worker %d: processing %s\n", id, path)
		time.Sleep(100 * time.Millisecond)

		// Step 3: Send result
		result.Result = fmt.Sprintf("processed-%s", path)
		p.results <- result
	}
}

// Process sends paths to workers and returns results channel
func (p *ImageProcessor) Process(paths []string) <-chan ProcessedImage {
	// Send all paths to jobs channel in background
	go func() {
		for _, path := range paths {
			p.jobs <- path
		}
		close(p.jobs)
	}()

	return p.results
}

func main() {
	paths := []string{
		"image1.jpg", "image2.jpg", "image3.jpg",
		"image4.jpg", "image5.jpg", "image6.jpg",
	}

	// Create processor with 2 workers
	processor := NewImageProcessor(2)

	// Process all images and collect results
	for result := range processor.Process(paths) {
		if result.Err != nil {
			fmt.Printf("Error: %s: %v\n", result.Path, result.Err)
		} else {
			fmt.Printf("Completed: %s\n", result.Result)
		}
	}
}

