import (
	"fmt"
	"runtime"
)

func main() {
	// CPU-bound: match core count
	cpuWorkers := runtime.NumCPU()
	fmt.Printf("CPU-bound workers: %d\n", cpuWorkers)

	// I/O-bound: more workers to overlap waiting
	ioWorkers := runtime.NumCPU() * 10
	fmt.Printf("I/O-bound workers: %d\n", ioWorkers)

	// Memory-limited: based on available RAM
	memoryPerWorker := int64(100 * 1024 * 1024) // 100MB per worker
	availableMemory := int64(8 * 1024 * 1024 * 1024) // 8GB
	memWorkers := int(availableMemory / memoryPerWorker)
	fmt.Printf("Memory-limited workers: %d\n", memWorkers)

	// GOMAXPROCS controls actual parallelism
	fmt.Printf("GOMAXPROCS: %d\n", runtime.GOMAXPROCS(0))
}

