import (
	"context"
	"fmt"
	"sync"
	"time"
)

type WorkerPool struct {
	jobs    chan func()
	wg      sync.WaitGroup
	ctx     context.Context
	cancel  context.CancelFunc
}

func NewWorkerPool(workers int) *WorkerPool {
	ctx, cancel := context.WithCancel(context.Background())
	p := &WorkerPool{
		jobs:   make(chan func(), 100),
		ctx:    ctx,
		cancel: cancel,
	}

	for i := 0; i < workers; i++ {
		p.wg.Add(1)
		go p.worker(i)
	}

	return p
}

func (p *WorkerPool) worker(id int) {
	defer p.wg.Done()

	for {
		select {
		case <-p.ctx.Done():
			fmt.Printf("Worker %d: shutting down\n", id)
			return
		case job, ok := <-p.jobs:
			if !ok {
				return // Channel closed
			}
			job()
		}
	}
}

func (p *WorkerPool) Submit(job func()) {
	select {
	case p.jobs <- job:
	case <-p.ctx.Done():
		// Pool is shutting down, job not submitted
	}
}

func (p *WorkerPool) Shutdown(timeout time.Duration) {
	p.cancel() // Signal workers to stop

	// Wait with timeout
	done := make(chan struct{})
	go func() {
		p.wg.Wait()
		close(done)
	}()

	select {
	case <-done:
		fmt.Println("All workers stopped gracefully")
	case <-time.After(timeout):
		fmt.Println("Shutdown timed out")
	}
}

func main() {
	pool := NewWorkerPool(3)

	// Submit some jobs
	for i := 0; i < 10; i++ {
		jobID := i
		pool.Submit(func() {
			fmt.Printf("Executing job %d\n", jobID)
			time.Sleep(100 * time.Millisecond)
		})
	}

	time.Sleep(300 * time.Millisecond)

	// Graceful shutdown
	pool.Shutdown(2 * time.Second)
}

