import "fmt"

// gen sends numbers 1 to n on the returned channel
func gen(nums ...int) <-chan int {
	out := make(chan int)
	go func() {
		for _, n := range nums {
			out <- n
		}
		close(out)
	}()
	return out
}

// sq squares each number received and sends results
func sq(in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		for n := range in {
			out <- n * n
		}
		close(out)
	}()
	return out
}

func main() {
	// Set up the pipeline: gen -> sq -> print
	numbers := gen(2, 3, 4, 5)
	squared := sq(numbers)

	// Consume results
	for result := range squared {
		fmt.Println(result)
	}
}

