package main

import "fmt"

func gen(nums ...int) <-chan int {
	out := make(chan int)
	go func() {
		for _, n := range nums {
			out <- n
		}
		close(out)
	}()
	return out
}

func sq(in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		for n := range in {
			out <- n * n
		}
		close(out)
	}()
	return out
}

// addOne adds 1 to each number
func addOne(in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		for n := range in {
			out <- n + 1
		}
		close(out)
	}()
	return out
}

// filter keeps only values passing the predicate
func filter(in <-chan int, keep func(int) bool) <-chan int {
	out := make(chan int)
	go func() {
		for n := range in {
			if keep(n) {
				out <- n
			}
		}
		close(out)
	}()
	return out
}

func main() {
	// Pipeline: gen -> sq -> filter(>10) -> addOne
	numbers := gen(1, 2, 3, 4, 5)
	squared := sq(numbers)
	filtered := filter(squared, func(n int) bool { return n > 10 })
	results := addOne(filtered)

	for r := range results {
		fmt.Println(r)
	}
}

// Output:
