// slowSquare simulates a slow operation
func slowSquare(in <-chan int, workerID int) <-chan int {
	out := make(chan int)
	go func() {
		for n := range in {
			time.Sleep(100 * time.Millisecond) // Simulate slow work
			fmt.Printf("Worker %d: squaring %d\n", workerID, n)
			out <- n * n
		}
		close(out)
	}()
	return out
}

func main() {
