	worker2 := slowSquare(numbers, 2)
	worker3 := slowSquare(numbers, 3)

	// Each number goes to exactly one worker
	// Results come from all three channels

	// We need to merge results (see fan-in next)
	_ = worker1
	_ = worker2
	_ = worker3
