// gen sends numbers until cancelled
func gen(ctx context.Context) <-chan int {
	out := make(chan int)
	n := 1
	go func() {
		defer close(out)
		for {
			select {
			case <-ctx.Done():
				fmt.Println("gen: cancelled")
				return
			case out <- n:
				n++
			}
		}
	}()
	return out
}

// sq squares numbers, respecting cancellation
func sq(ctx context.Context, in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for n := range in {
			select {
			case <-ctx.Done():
				fmt.Println("sq: cancelled")
				return
			case out <- n * n:
			}
		}
	}()
	return out
}

func main() {
	// Create cancellable context
	ctx, cancel := context.WithCancel(context.Background())

	numbers := gen(ctx)
	squared := sq(ctx, numbers)

	// Consume only 5 results, then cancel
	for i := 0; i < 5; i++ {
		fmt.Println(<-squared)
	}

	cancel() // Stop the pipeline
	time.Sleep(100 * time.Millisecond) // Let goroutines clean up
	fmt.Println("Done")
}

