package main

import (
	"context"
	"fmt"
	"strconv"
	"strings"
	"sync"
)

type Record struct {
	ID    int
	Name  string
	Value float64
}

type Result struct {
	Record   Record
	Computed float64
	Err      error
}

// parseRecords reads CSV lines and parses into Records
func parseRecords(ctx context.Context, lines <-chan string) <-chan Record {
	out := make(chan Record)
	go func() {
		defer close(out)
		for line := range lines {
			select {
			case <-ctx.Done():
				return
			default:
			}

			parts := strings.Split(line, ",")
			if len(parts) != 3 {
				continue // Skip malformed
			}

			id, _ := strconv.Atoi(parts[0])
			value, _ := strconv.ParseFloat(parts[2], 64)

			out <- Record{ID: id, Name: parts[1], Value: value}
		}
	}()
	return out
}

// transform applies business logic to each record
func transform(ctx context.Context, records <-chan Record, workerID int) <-chan Result {
	out := make(chan Result)
	go func() {
		defer close(out)
		for rec := range records {
			select {
			case <-ctx.Done():
				return
			default:
			}

			// Simulate complex computation
			computed := rec.Value * 1.15 // Add 15%

			out <- Result{
				Record:   rec,
				Computed: computed,
			}
		}
	}()
	return out
}

// merge combines results from multiple workers
func mergeResults(ctx context.Context, channels ...<-chan Result) <-chan Result {
	out := make(chan Result)
	var wg sync.WaitGroup

	for _, ch := range channels {
		wg.Add(1)
		go func(c <-chan Result) {
			defer wg.Done()
			for r := range c {
				select {
				case <-ctx.Done():
					return
				case out <- r:
				}
			}
		}(ch)
	}

	go func() {
		wg.Wait()
		close(out)
	}()

	return out
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Simulate CSV input
	lines := make(chan string)
	go func() {
		defer close(lines)
		data := []string{
			"1,Alice,100.50",
			"2,Bob,200.75",
			"3,Carol,150.25",
			"4,David,300.00",
			"5,Eve,250.50",
		}
		for _, line := range data {
			lines <- line
		}
	}()

	// Pipeline: parse -> transform (fan-out) -> merge (fan-in)
	records := parseRecords(ctx, lines)

	// Fan-out to 2 workers
	w1 := transform(ctx, records, 1)
	w2 := transform(ctx, records, 2)

	// Fan-in results
	results := mergeResults(ctx, w1, w2)

	// Consume and output
	for r := range results {
		fmt.Printf("%s: %.2f -> %.2f\n", r.Record.Name, r.Record.Value, r.Computed)
	}
}

