// Happens-before guarantees (conceptual illustrations)

// Rule 1: Within a goroutine, statements execute in order
a = 1
b = 2  // b = 2 happens-after a = 1 (sequential code)

// Rule 2: Channel send happens-before corresponding receive
ch <- x    // send completes
y := <-ch  // receive sees the value x that was sent

// Rule 3: Closing a channel happens-before receive of zero value
close(ch)
v, ok := <-ch  // ok is false, v is zero value

// Rule 4: Unlock() happens-before subsequent Lock()
mu.Lock()
x = 1
mu.Unlock()    // Unlock happens-before...

mu.Lock()      // ...the next Lock on the same mutex
fmt.Println(x) // Guaranteed to see x = 1
mu.Unlock()

// Rule 5: sync.Once.Do: the function completes before Do returns
once.Do(func() { x = 1 })
fmt.Println(x) // All goroutines see x = 1 after their Do returns

