import (
	"fmt"
	"sync"
)

func main() {
	var wg sync.WaitGroup

	// Go 1.22+ creates a new 'i' each iteration, so this works correctly.
	// Pre-1.22, all goroutines would print "3" (the final value).
	for i := 0; i < 3; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			fmt.Println(i)
		}()
	}
	wg.Wait()

	fmt.Println("---")

	// Explicit argument passing: clearer and works in all Go versions
	for i := 0; i < 3; i++ {
		wg.Add(1)
		go func(n int) {
			defer wg.Done()
			fmt.Println(n)
		}(i)  // Pass i as argument, creating a copy
	}
	wg.Wait()
}

