import (
	"sync"
	"time"
)

var mu1, mu2 sync.Mutex

func main() {
	// Goroutine A: lock mu1, then mu2
	go func() {
		mu1.Lock()
		time.Sleep(10 * time.Millisecond) // Increases chance of deadlock
		mu2.Lock()                         // Waits here if B has mu2
		// ... do work ...
		mu2.Unlock()
		mu1.Unlock()
	}()

	// Goroutine B: lock mu2, then mu1 (OPPOSITE ORDER!)
	go func() {
		mu2.Lock()
		time.Sleep(10 * time.Millisecond)
		mu1.Lock() // DEADLOCK: A holds mu1, wants mu2; B holds mu2, wants mu1
		// ... do work ...
		mu1.Unlock()
		mu2.Unlock()
	}()

	time.Sleep(1 * time.Second)
}

