	"fmt"
	"time"
)

func main() {
	ch := make(chan int)

	// Pattern 1: Timeout
	select {
	case v := <-ch:
		fmt.Println("Got:", v)
	case <-time.After(1 * time.Second):
		fmt.Println("Timeout: no data received")
	}

	// Pattern 2: Context with deadline
	ctx, cancel := context.WithTimeout(context.Background(), 1*time.Second)
	defer cancel()

	select {
	case v := <-ch:
		fmt.Println("Got:", v)
	case <-ctx.Done():
		fmt.Println("Context expired:", ctx.Err())
	}

	// Pattern 3: Non-blocking check
	select {
	case v := <-ch:
		fmt.Println("Got:", v)
	default:
		fmt.Println("Nothing available right now")
	}
}

