		ReadTimeout:  15 * time.Second,
		WriteTimeout: 15 * time.Second,
		IdleTimeout:  60 * time.Second,
	}

	return s
}

func (s *Server) handleRoot(w http.ResponseWriter, r *http.Request) {
	// Simulate some work
	time.Sleep(100 * time.Millisecond)
	fmt.Fprintln(w, "OK")
}

func (s *Server) handleHealth(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	fmt.Fprintln(w, "healthy")
}

// Background worker that respects context cancellation
func (s *Server) runBackgroundJob(ctx context.Context, name string) {
	s.wg.Add(1)
	go func() {
		defer s.wg.Done()

		ticker := time.NewTicker(5 * time.Second)
		defer ticker.Stop()

		fmt.Printf("[%s] Background job started\n", name)

		for {
			select {
			case <-ctx.Done():
				fmt.Printf("[%s] Background job stopping\n", name)
				return
			case <-ticker.C:
				fmt.Printf("[%s] Tick\n", name)
			}
		}
	}()
}

func (s *Server) Start(ctx context.Context) error {
	// Start background jobs
	s.runBackgroundJob(ctx, "metrics-collector")
	s.runBackgroundJob(ctx, "cache-warmer")

	// Start HTTP server
	go func() {
		fmt.Printf("HTTP server listening on %s\n", s.httpServer.Addr)
		if err := s.httpServer.ListenAndServe(); !errors.Is(err, http.ErrServerClosed) {
			fmt.Printf("HTTP server error: %v\n", err)
		}
	}()

	return nil
}

func (s *Server) Shutdown(ctx context.Context) error {
	fmt.Println("Initiating graceful shutdown...")

	// Shutdown HTTP server (stops accepting, waits for active requests)
	if err := s.httpServer.Shutdown(ctx); err != nil {
		return fmt.Errorf("HTTP shutdown: %w", err)
	}
	fmt.Println("HTTP server stopped")

	// Wait for background jobs (they should stop when ctx is canceled)
	done := make(chan struct{})
	go func() {
		s.wg.Wait()
		close(done)
	}()

	select {
	case <-done:
		fmt.Println("All background jobs stopped")
	case <-ctx.Done():
		return fmt.Errorf("timeout waiting for background jobs")
	}

	return nil
}

func main() {
	// Create root context that cancels on shutdown signals
	ctx, stop := signal.NotifyContext(
		context.Background(),
		syscall.SIGINT,
		syscall.SIGTERM,
	)
	defer stop()

	// Create and start server
	server := NewServer(":8080")
	if err := server.Start(ctx); err != nil {
		fmt.Printf("Failed to start: %v\n", err)
		os.Exit(1)
	}

	// Wait for shutdown signal
	<-ctx.Done()
	stop() // Stop receiving more signals

	fmt.Println("\nShutdown signal received")

	// Create shutdown context with timeout
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 25*time.Second)
	defer cancel()

	// Perform graceful shutdown
	if err := server.Shutdown(shutdownCtx); err != nil {
		fmt.Printf("Shutdown error: %v\n", err)
		os.Exit(1)
	}

	fmt.Println("Server exited cleanly")
}

