fmt.Println(clone)     // [99 2 3 4 5]

// Original 2D grid
grid := [][]int{
    {1, 2, 3},
    {4, 5, 6},
}

// WRONG: shallow copy - inner slices still shared!
shallowCopy := append([][]int{}, grid...)
shallowCopy[0][0] = 99
fmt.Println(grid[0][0])  // 99 - original changed!

// CORRECT: deep copy - copy each row
deepCopy := make([][]int, len(grid))
