fmt.Println(grid[0][0])  // 1 - original unchanged

// Insert val at index i
func insert(s []int, i int, val int) []int {
    // Append zero to make room
    s = append(s, 0)
    // Shift elements right
    copy(s[i+1:], s[i:])
    // Insert new value
    s[i] = val
    return s
}

// Example
s := []int{1, 2, 4, 5}
s = insert(s, 2, 3)  // Insert 3 at index 2
fmt.Println(s)       // [1 2 3 4 5]

// One-liner (creates temporary slice, less efficient)
s = append(s[:i], append([]int{val}, s[i:]...)...)

// Delete at index i, PRESERVE order - O(n)
func deleteOrdered(s []int, i int) []int {
    return append(s[:i], s[i+1:]...)
}

// Delete at index i, ORDER DOESN'T MATTER - O(1)
func deleteFast(s []int, i int) []int {
    s[i] = s[len(s)-1]  // Replace with last element
    return s[:len(s)-1]  // Shrink slice
}

// Examples
s1 := []int{1, 2, 3, 4, 5}
s1 = deleteOrdered(s1, 2)  // Delete index 2 (value 3)
fmt.Println(s1)             // [1 2 4 5] - order preserved

s2 := []int{1, 2, 3, 4, 5}
s2 = deleteFast(s2, 2)      // Delete index 2 (value 3)
fmt.Println(s2)             // [1 2 5 4] - 5 moved to index 2

// Remove all zeros in-place
func removeZeros(nums []int) []int {
    writeIdx := 0
    for _, v := range nums {
        if v != 0 {
            nums[writeIdx] = v
            writeIdx++
        }
    }
    return nums[:writeIdx]
}

// Example
nums := []int{0, 1, 0, 2, 0, 3}
result := removeZeros(nums)
fmt.Println(result)  // [1 2 3]

// Generic filter (Go 1.18+ generics)
func filter[T any](s []T, keep func(T) bool) []T {
    n := 0
    for _, v := range s {
        if keep(v) {
            s[n] = v
            n++
        }
    }
    return s[:n]
}

// Usage: keep only positive numbers
nums := []int{-1, 2, -3, 4, -5}
positive := filter(nums, func(x int) bool { return x > 0 })
// positive = [2 4]

// Reverse entire slice in-place
func reverse(s []int) {
    for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
        s[i], s[j] = s[j], s[i]
    }
}

// Reverse a portion [start, end] inclusive
func reversePart(s []int, start, end int) {
    for start < end {
        s[start], s[end] = s[end], s[start]
        start++
        end--
    }
}

// Example
nums := []int{1, 2, 3, 4, 5}
reverse(nums)
fmt.Println(nums)  // [5 4 3 2 1]

// Rotate array right by k positions
func rotate(nums []int, k int) {
    n := len(nums)
    k = k % n  // Handle k > n

    // Reverse all: [1,2,3,4,5] -> [5,4,3,2,1]
    reverse(nums)
    // Reverse first k: [5,4,3,2,1] -> [4,5,3,2,1] (k=2)
    reversePart(nums, 0, k-1)
    // Reverse rest: [4,5,3,2,1] -> [4,5,1,2,3]
    reversePart(nums, k, n-1)
}

// Example: rotate [1,2,3,4,5] by 2
// Step 1: [5,4,3,2,1] (reverse all)
// Step 2: [4,5,3,2,1] (reverse first 2)
// Step 3: [4,5,1,2,3] (reverse last 3)
// Result: [4,5,1,2,3] - rotated right by 2

// BAD: many reallocations as slice grows
func collectBad(n int) []int {
    result := []int{}  // Capacity 0
    for i := 0; i < n; i++ {
        result = append(result, i)  // May reallocate!
    }
    return result
}

// GOOD: pre-allocate capacity
func collectGood(n int) []int {
    result := make([]int, 0, n)  // Length 0, capacity n
    for i := 0; i < n; i++ {
        result = append(result, i)  // No reallocation
    }
    return result
}

// ALSO GOOD: if you know exact size, set length directly
func collectDirect(n int) []int {
    result := make([]int, n)  // Length n, all zeros
    for i := 0; i < n; i++ {
        result[i] = i  // Direct assignment
    }
    return result
}

