// Get sorted indices without modifying original array
func sortedIndices(nums []int) []int {
    indices := make([]int, len(nums))
    for i := range indices {
        indices[i] = i
    }

    // Sort indices by the values they point to
    sort.Slice(indices, func(i, j int) bool {
        return nums[indices[i]] < nums[indices[j]]
    })

    return indices
}

