import "sort"

func sortByFrequency(nums []int) []int {
    // Count frequencies
    freq := make(map[int]int)
    for _, n := range nums {
        freq[n]++
    }

    // Sort by frequency (descending), then by value (ascending) for ties
    sort.Slice(nums, func(i, j int) bool {
        if freq[nums[i]] != freq[nums[j]] {
            return freq[nums[i]] > freq[nums[j]]  // Higher frequency first
        }
        return nums[i] < nums[j]  // Smaller value first for ties
    })

    return nums
}

