import "cmp"

// any: can be literally any type
func Identity[T any](v T) T {
    return v
}

// comparable: must support == and !=
func Contains[T comparable](slice []T, target T) bool {
    for _, v := range slice {
        if v == target {  // == requires comparable
            return true
        }
    }
    return false
}

// cmp.Ordered: must support < > <= >=
func Max[T cmp.Ordered](a, b T) T {
    if a > b {  // > requires Ordered
        return a
    }
    return b
}

import "cmp"

// Generic Min - works with int, float64, string, etc.
func Min[T cmp.Ordered](a, b T) T {
    if a < b {
        return a
    }
    return b
}

// Generic Max
func Max[T cmp.Ordered](a, b T) T {
    if a > b {
        return a
    }
    return b
}

// Variadic version: min/max of multiple values
func MinOf[T cmp.Ordered](values ...T) T {
    if len(values) == 0 {
        panic("MinOf requires at least one argument")
    }
    result := values[0]
    for _, v := range values[1:] {
        if v < result {
            result = v
        }
    }
    return result
}

// Usage
min := Min(10, 20)              // 10
