func subsetsBuggy(nums []int) [][]int {
    result := [][]int{}
    current := []int{}

    var backtrack func(start int)
    backtrack = func(start int) {
        result = append(result, current)  // Stores reference, not copy!
        for i := start; i < len(nums); i++ {
            current = append(current, nums[i])
            backtrack(i + 1)
            current = current[:len(current)-1]  // This modifies ALL stored results!
        }
    }
    backtrack(0)
    return result  // All entries are the same (empty) slice!
}

// FIX: Make a copy before storing
func subsetsFixed(nums []int) [][]int {
    result := [][]int{}
    current := []int{}

    var backtrack func(start int)
    backtrack = func(start int) {
        // Create a NEW slice with a COPY of current's elements
        copy := append([]int{}, current...)
        result = append(result, copy)

        for i := start; i < len(nums); i++ {
            current = append(current, nums[i])
            backtrack(i + 1)
            current = current[:len(current)-1]
        }
    }
    backtrack(0)
    return result
}

