import "math"

// Check if a + b would overflow
func addWouldOverflow(a, b int64) bool {
    if b > 0 {
        return a > math.MaxInt64 - b
    }
    return a < math.MinInt64 - b
}

// Check if a * b would overflow
func mulWouldOverflow(a, b int64) bool {
    if a == 0 || b == 0 {
        return false
    }
    result := a * b
    return result/a != b
}

